import asyncio
import base64
import io
import json
from PIL import Image
import numpy as np
from mcp import ClientSession
from mcp.client.streamable_http import streamablehttp_client

MCP_URL = "http://loophole-sim:8000/mcp"

class LoopholeClient:
    def __init__(self, url=MCP_URL):
        self.url = url

    async def _call(self, tool_name, arguments=None):
        async with streamablehttp_client(self.url) as (read_stream, write_stream, _):
            async with ClientSession(read_stream, write_stream) as session:
                await session.initialize()
                result = await session.call_tool(tool_name, arguments or {})
                return result

    async def list_tools(self):
        async with streamablehttp_client(self.url) as (read_stream, write_stream, _):
            async with ClientSession(read_stream, write_stream) as session:
                await session.initialize()
                return await session.list_tools()

    def call(self, tool_name, **kwargs):
        return asyncio.run(self._call(tool_name, kwargs))

    def get_state(self):
        res = self.call("get_state")
        for c in res.content:
            if c.type == "text":
                return json.loads(c.text)
        raise RuntimeError(f"Unexpected get_state result: {res}")

    def get_contacts(self):
        res = self.call("get_contacts")
        for c in res.content:
            if c.type == "text":
                return json.loads(c.text)
        raise RuntimeError(f"Unexpected get_contacts result: {res}")

    def render(self, **kwargs):
        res = self.call("render", **kwargs)
        meta = None
        images = []
        for c in res.content:
            if c.type == "text":
                meta = json.loads(c.text)
            elif c.type == "image":
                raw = base64.b64decode(c.data)
                img = Image.open(io.BytesIO(raw))
                images.append(np.array(img))
        return meta, images

if __name__ == "__main__":
    client = LoopholeClient()
    tools = asyncio.run(client.list_tools())
    print("TOOLS:", [t.name for t in tools.tools])
    state = client.get_state()
    print("STATE:", json.dumps(state, indent=2))

