import asyncio
import base64
import io
import json
import time
from PIL import Image
import numpy as np
from mcp import ClientSession
from mcp.client.streamable_http import streamablehttp_client

MCP_URL = "http://loophole-sim:8000/mcp"

def parse_text(res):
    for c in res.content:
        if c.type == "text":
            return json.loads(c.text)
    raise RuntimeError(f"Unexpected result: {res}")

def parse_render(res):
    meta = None
    images = []
    for c in res.content:
        if c.type == "text":
            meta = json.loads(c.text)
        elif c.type == "image":
            raw = base64.b64decode(c.data)
            img = Image.open(io.BytesIO(raw))
            images.append(np.array(img))
    return meta, images

class LoopholeClient:
    def __init__(self, url=MCP_URL):
        self.url = url

    async def run_batch(self, fn):
        async with streamablehttp_client(self.url) as (read_stream, write_stream, _):
            async with ClientSession(read_stream, write_stream) as session:
                await session.initialize()
                return await fn(session)

    def call(self, tool_name, **kwargs):
        async def _do(session):
            return await session.call_tool(tool_name, kwargs)
        return asyncio.run(self.run_batch(_do))

    def get_state(self):
        return parse_text(self.call("get_state"))

    def get_contacts(self):
        return parse_text(self.call("get_contacts"))

    def render(self, **kwargs):
        return parse_render(self.call("render", **kwargs))

if __name__ == "__main__":
    c = LoopholeClient()
    t0 = time.time()
    async def test(session):
        for i in range(3):
            ti = time.time()
            res = await session.call_tool("render", {
                "view": "iso",
                "modalities": ["depth", "segmentation"],
                "depth_format": "metric",
                "width": 640,
                "height": 480
            })
            meta, imgs = parse_render(res)
            print(f"Render {i}: {time.time()-ti:.3f}s, shapes={[im.shape for im in imgs]}", flush=True)
    asyncio.run(c.run_batch(test))
    print(f"Total: {time.time()-t0:.3f}s", flush=True)

