    auto compute_bottleneck = [&](const std::vector<Pose>& pth) {
        double mc = 1.0;
        for (size_t i = 0; i + 1 < pth.size(); ++i) {
            mc = std::min(mc, scene.edge_min_clearance(pth[i], pth[i + 1]));
        }
