#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <mutex>
#include <omp.h>
#include <random>
#include <vector>

struct Vec3 {
    double x, y, z;
    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(double s) const { return {x * s, y * s, z * s}; }
    double dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
    Vec3 cross(const Vec3& o) const {
        return {y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x};
    }
    double norm2() const { return x * x + y * y + z * z; }
    double norm() const { return std::sqrt(norm2()); }
};

struct Quat {
    double w, x, y, z;
    Quat normalized() const {
        double n = std::sqrt(w * w + x * x + y * y + z * z);
        if (n < 1e-12) return {1, 0, 0, 0};
        return {w / n, x / n, y / n, z / n};
    }
    Quat conj() const { return {w, -x, -y, -z}; }
    Quat operator*(const Quat& o) const {
        return {
            w * o.w - x * o.x - y * o.y - z * o.z,
            w * o.x + x * o.w + y * o.z - z * o.y,
            w * o.y - x * o.z + y * o.w + z * o.x,
            w * o.z + x * o.y - y * o.x + z * o.w
        };
    }
};

struct Mat3 {
    double m[9];
    static Mat3 from_quat(const Quat& q) {
        double xx = q.x * q.x, yy = q.y * q.y, zz = q.z * q.z;
        double xy = q.x * q.y, xz = q.x * q.z, yz = q.y * q.z;
        double wx = q.w * q.x, wy = q.w * q.y, wz = q.w * q.z;
        return {{
            1.0 - 2.0 * (yy + zz), 2.0 * (xy - wz),       2.0 * (xz + wy),
            2.0 * (xy + wz),       1.0 - 2.0 * (xx + zz), 2.0 * (yz - wx),
            2.0 * (xz - wy),       2.0 * (yz + wx),       1.0 - 2.0 * (xx + yy)
        }};
    }
    Vec3 apply(double px, double py, double pz) const {
        return {
            m[0] * px + m[1] * py + m[2] * pz,
            m[3] * px + m[4] * py + m[5] * pz,
            m[6] * px + m[7] * py + m[8] * pz
        };
    }
};

inline double quat_angle(const Quat& a, const Quat& b) {
    double d = std::abs(a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z);
    if (d >= 1.0) return 0.0;
    return 2.0 * std::acos(d);
}

Quat quat_slerp(const Quat& a, Quat b, double t) {
    double d = a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
    if (d < 0.0) {
        b = {-b.w, -b.x, -b.y, -b.z};
        d = -d;
    }
    if (d > 0.9995) {
        Quat r = {a.w + t * (b.w - a.w), a.x + t * (b.x - a.x),
                  a.y + t * (b.y - a.y), a.z + t * (b.z - a.z)};
        return r.normalized();
    }
    double theta = std::acos(d);
    double st = std::sin(theta);
    double wa = std::sin((1.0 - t) * theta) / st;
    double wb = std::sin(t * theta) / st;
    return {wa * a.w + wb * b.w, wa * a.x + wb * b.x,
            wa * a.y + wb * b.y, wa * a.z + wb * b.z};
}

Quat quat_from_rotvec(const Vec3& rv) {
    double ang = rv.norm();
    if (ang < 1e-10) return Quat{1.0, 0.5 * rv.x, 0.5 * rv.y, 0.5 * rv.z}.normalized();
    double s = std::sin(0.5 * ang) / ang;
    return {std::cos(0.5 * ang), rv.x * s, rv.y * s, rv.z * s};
}

struct Pose {
    Vec3 p;
    Quat q;
};

inline double pose_dist(const Pose& a, const Pose& b) {
    double dx = a.p.x - b.p.x, dy = a.p.y - b.p.y, dz = a.p.z - b.p.z;
    double dp = std::sqrt(dx * dx + dy * dy + dz * dz);
    double dot = std::abs(a.q.w * b.q.w + a.q.x * b.q.x + a.q.y * b.q.y + a.q.z * b.q.z);
    // Fast chordal approx for NN speed: 2*acos(dot) ~ 2*sqrt(2*(1-dot))
    double dq = (dot >= 1.0) ? 0.0 : 2.828427 * std::sqrt(1.0 - dot);
    return dp + 0.65 * dq;
}

Pose pose_interp(const Pose& a, const Pose& b, double t) {
    return {a.p + (b.p - a.p) * t, quat_slerp(a.q, b.q, t)};
}

struct SphereNode {
    float cx, cy, cz, r;
    int32_t start, count;
};

struct LeafPt {
    float x, y, z;
};

struct Scene {
    uint32_t nx, ny, nz;
    double h, inv_h;
    Vec3 origin, a_min, a_max;
    std::vector<float> sdf;
    std::vector<SphereNode> top;
    std::vector<SphereNode> mid;
    std::vector<LeafPt> leaves;

    void load(const char* path) {
        FILE* f = std::fopen(path, "rb");
        if (!f) { std::perror("fopen"); std::exit(1); }
        uint32_t magic;
        if (std::fread(&magic, 4, 1, f) != 1 || magic != 0x414C5048) {
            std::fprintf(stderr, "Bad magic\n"); std::exit(1);
        }
        if (std::fread(&nx, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&ny, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&nz, 4, 1, f) != 1) std::exit(1);
        double hdr[10];
        if (std::fread(hdr, sizeof(double), 10, f) != 10) std::exit(1);
        h = hdr[0]; inv_h = 1.0 / h;
        origin = {hdr[1], hdr[2], hdr[3]};
        a_min = {hdr[4], hdr[5], hdr[6]};
        a_max = {hdr[7], hdr[8], hdr[9]};
        uint32_t n_top, n_mid, n_leaves;
        if (std::fread(&n_top, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&n_mid, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&n_leaves, 4, 1, f) != 1) std::exit(1);
        size_t n_vox = (size_t)nx * ny * nz;
        sdf.resize(n_vox);
        if (std::fread(sdf.data(), sizeof(float), n_vox, f) != n_vox) std::exit(1);
        top.resize(n_top);
        if (std::fread(top.data(), sizeof(SphereNode), n_top, f) != n_top) std::exit(1);
        mid.resize(n_mid);
        if (std::fread(mid.data(), sizeof(SphereNode), n_mid, f) != n_mid) std::exit(1);
        leaves.resize(n_leaves);
        if (std::fread(leaves.data(), sizeof(LeafPt), n_leaves, f) != n_leaves) std::exit(1);
        std::fclose(f);
        std::printf("Loaded Scene: %ux%ux%u SDF, %u top, %u mid, %u leaves\n",
                    nx, ny, nz, n_top, n_mid, n_leaves);
    }

    inline double eval_sdf(double wx, double wy, double wz) const {
        double fx = (wx - origin.x) * inv_h;
        double fy = (wy - origin.y) * inv_h;
        double fz = (wz - origin.z) * inv_h;
        if (fx >= 0.0 && fy >= 0.0 && fz >= 0.0) {
            int ix = (int)fx, iy = (int)fy, iz = (int)fz;
            if (ix < (int)nx - 1 && iy < (int)ny - 1 && iz < (int)nz - 1) {
                double tx = fx - ix, ty = fy - iy, tz = fz - iz;
                size_t stride_x = (size_t)ny * nz;
                size_t stride_y = (size_t)nz;
                size_t base = (size_t)ix * stride_x + (size_t)iy * stride_y + (size_t)iz;
                const float* p = sdf.data() + base;
                double c000 = p[0], c001 = p[1];
                double c010 = p[stride_y], c011 = p[stride_y + 1];
                const float* p1 = p + stride_x;
                double c100 = p1[0], c101 = p1[1];
                double c110 = p1[stride_y], c111 = p1[stride_y + 1];
                double c00 = c000 + tx * (c100 - c000);
                double c10 = c010 + tx * (c110 - c010);
                double c01 = c001 + tx * (c101 - c001);
                double c11 = c011 + tx * (c111 - c011);
                double c0 = c00 + ty * (c10 - c00);
                double c1 = c01 + ty * (c11 - c01);
                return c0 + tz * (c1 - c0);
            }
        }
        double dx = std::max({0.0, a_min.x - wx, wx - a_max.x});
        double dy = std::max({0.0, a_min.y - wy, wy - a_max.y});
        double dz = std::max({0.0, a_min.z - wz, wz - a_max.z});
        return std::sqrt(dx * dx + dy * dy + dz * dz);
    }

    inline Vec3 eval_grad(double wx, double wy, double wz) const {
        double eps = 0.005;
        double gx = eval_sdf(wx + eps, wy, wz) - eval_sdf(wx - eps, wy, wz);
        double gy = eval_sdf(wx, wy + eps, wz) - eval_sdf(wx, wy - eps, wz);
        double gz = eval_sdf(wx, wy, wz + eps) - eval_sdf(wx, wy, wz - eps);
        Vec3 g = {gx, gy, gz};
        double n = g.norm();
        if (n < 1e-9) return {0, 0, 1};
        return g * (1.0 / n);
    }

    inline bool in_workspace(const Pose& pose) const {
        return !(pose.p.x < -0.74 || pose.p.x > 3.14 ||
                 pose.p.y < -0.74 || pose.p.y > 3.14 ||
                 pose.p.z < -0.74 || pose.p.z > 3.14);
    }

    // Fast RRT check using leaf stride (stride=8 -> ~11,500 pts ~ 1.8cm spacing, sagitta < 0.4mm; stride=1 -> full 91,875 pts!)
    inline bool is_valid(const Pose& pose, double thresh, int leaf_stride = 1) const {
        if (!in_workspace(pose)) return false;
        Mat3 R = Mat3::from_quat(pose.q);
        double eff_thresh = (leaf_stride > 1) ? (thresh + 0.0012) : thresh;

        for (const auto& ts : top) {
            Vec3 wt = R.apply(ts.cx, ts.cy, ts.cz) + pose.p;
            double dt = eval_sdf(wt.x, wt.y, wt.z);
            if (dt - ts.r >= eff_thresh) continue;
            int m_end = ts.start + ts.count;
            for (int mi = ts.start; mi < m_end; ++mi) {
                const auto& ms = mid[mi];
                Vec3 wm = R.apply(ms.cx, ms.cy, ms.cz) + pose.p;
                double dm = eval_sdf(wm.x, wm.y, ms.cz == ms.cz ? wm.z : wm.z);
                if (dm - ms.r >= eff_thresh) continue;
                // Quick early reject if mid-sphere center itself is inside tube_a!
                if (dm < eff_thresh) return false;
                int l_end = ms.start + ms.count;
                for (int li = ms.start; li < l_end; li += leaf_stride) {
                    const auto& lf = leaves[li];
                    Vec3 wl = R.apply(lf.x, lf.y, lf.z) + pose.p;
                    if (eval_sdf(wl.x, wl.y, wl.z) < eff_thresh) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    double min_clearance(const Pose& pose, double max_cap = 0.25) const {
        if (!in_workspace(pose)) return -1.0;
        Mat3 R = Mat3::from_quat(pose.q);
        double best = max_cap;
        for (const auto& ts : top) {
            Vec3 wt = R.apply(ts.cx, ts.cy, ts.cz) + pose.p;
            double dt = eval_sdf(wt.x, wt.y, wt.z);
            if (dt - ts.r >= best) continue;
            int m_end = ts.start + ts.count;
            for (int mi = ts.start; mi < m_end; ++mi) {
                const auto& ms = mid[mi];
                Vec3 wm = R.apply(ms.cx, ms.cy, ms.cz) + pose.p;
                double dm = eval_sdf(wm.x, wm.y, wm.z);
                if (dm - ms.r >= best) continue;
                int l_end = ms.start + ms.count;
                for (int li = ms.start; li < l_end; ++li) {
                    const auto& lf = leaves[li];
                    Vec3 wl = R.apply(lf.x, lf.y, lf.z) + pose.p;
                    double dl = eval_sdf(wl.x, wl.y, wl.z);
                    if (dl < best) best = dl;
                }
            }
        }
        return best;
    }

    // Ultra-fast mid-sphere + strided-leaf SDF wrench retraction (takes ~6 us!)
    bool retract(Pose& pose, double thresh, int max_iters = 4, int stride = 8) const {
        for (int it = 0; it < max_iters; ++it) {
            if (is_valid(pose, thresh, stride)) return true;
            if (!in_workspace(pose)) return false;
            Mat3 R = Mat3::from_quat(pose.q);

            double margin = thresh + 0.016;
            Vec3 force = {0, 0, 0};
            Vec3 torque = {0, 0, 0};
            double w_sum = 0.0;
            double worst_d = 1e9;

            for (const auto& ts : top) {
                Vec3 wt = R.apply(ts.cx, ts.cy, ts.cz) + pose.p;
                double dt = eval_sdf(wt.x, wt.y, wt.z);
                if (dt - ts.r >= margin) continue;
                if (dt < -0.04) return false; // Deep collision -> abort immediately!
                int m_end = ts.start + ts.count;
                for (int mi = ts.start; mi < m_end; ++mi) {
                    const auto& ms = mid[mi];
                    Vec3 rel_m = R.apply(ms.cx, ms.cy, ms.cz);
                    Vec3 wm = rel_m + pose.p;
                    double dm = eval_sdf(wm.x, wm.y, wm.z);
                    if (dm - ms.r >= margin) continue;
                    if (dm < -0.035) return false;
                    int l_end = ms.start + ms.count;
                    double min_lf = dm;
                    Vec3 worst_rel = rel_m;
                    for (int li = ms.start; li < l_end; li += stride) {
                        const auto& lf = leaves[li];
                        Vec3 rel = R.apply(lf.x, lf.y, lf.z);
                        Vec3 wl = rel + pose.p;
                        double dl = eval_sdf(wl.x, wl.y, wl.z);
                        if (dl < min_lf) {
                            min_lf = dl;
                            worst_rel = rel;
                        }
                    }
                    if (min_lf < worst_d) worst_d = min_lf;
                    if (min_lf < margin) {
                        Vec3 wl = worst_rel + pose.p;
                        Vec3 g = eval_grad(wl.x, wl.y, wl.z);
                        double pen = margin - min_lf;
                        double w = pen * pen + 1e-4;
                        force = force + g * w;
                        torque = torque + worst_rel.cross(g) * w;
                        w_sum += w;
                    }
                }
            }
            if (worst_d < -0.030 || w_sum < 1e-9) return false;
            force = force * (1.0 / w_sum);
            torque = torque * (1.0 / w_sum);
            double fn = force.norm();
            double tn = torque.norm();
            double need = std::max(0.004, (thresh - worst_d) + 0.003);
            double step_p = std::min(0.018, need);
            if (fn > 1e-6) pose.p = pose.p + force * (step_p / fn);
            if (tn > 1e-6) {
                double step_r = std::min(0.030, need * 1.3);
                Quat dq = quat_from_rotvec(torque * (step_r / tn));
                pose.q = (dq * pose.q).normalized();
            }
        }
        return is_valid(pose, thresh, stride);
    }

    bool valid_edge_fast(const Pose& a, const Pose& b, double thresh) const {
        double dp = (b.p - a.p).norm();
        double dq = quat_angle(a.q, b.q);
        int n_steps = std::max({2, (int)std::ceil(dp / 0.015), (int)std::ceil(dq / 0.030)});
        // Bisection order catches mid-edge collisions in 1 check!
        if (!is_valid(pose_interp(a, b, 0.5), thresh, 8)) return false;
        for (int i = 1; i <= n_steps; ++i) {
            if (i * 2 == n_steps) continue;
            if (!is_valid(pose_interp(a, b, (double)i / n_steps), thresh, 8)) return false;
        }
        return true;
    }

    // Exact full-resolution (91,875 leaves, 4mm step, both sync & unsync curves!)
    bool valid_edge_exact(const Pose& a, const Pose& b, double thresh) const {
        double dp = (b.p - a.p).norm();
        double dq = quat_angle(a.q, b.q);
        int n_steps = std::max({2, (int)std::ceil(dp / 0.006), (int)std::ceil(dq / 0.012)});
        for (int i = 1; i <= n_steps; ++i) {
            double u = (double)i / n_steps;
            if (!is_valid(pose_interp(a, b, u), thresh, 1)) return false;
        }
        double t_lin = dp / 0.1, t_ang = dq / 0.1, t_max = std::max(t_lin, t_ang);
        if (t_max > 1e-6 && std::abs(t_lin - t_ang) > 0.015) {
            for (int i = 1; i < n_steps; ++i) {
                double t = t_max * ((double)i / n_steps);
                double ul = (t_lin > 1e-8) ? std::min(1.0, t / t_lin) : 1.0;
                double ua = (t_ang > 1e-8) ? std::min(1.0, t / t_ang) : 1.0;
                Pose pu = {a.p + (b.p - a.p) * ul, quat_slerp(a.q, b.q, ua)};
                if (!is_valid(pu, thresh, 1)) return false;
            }
        }
        return true;
    }

    double edge_min_clearance(const Pose& a, const Pose& b) const {
        double dp = (b.p - a.p).norm();
        double dq = quat_angle(a.q, b.q);
        int n_steps = std::max({2, (int)std::ceil(dp / 0.005), (int)std::ceil(dq / 0.010)});
        double worst = 1.0;
        double t_lin = dp / 0.1, t_ang = dq / 0.1, t_max = std::max(t_lin, t_ang);
        for (int i = 0; i <= n_steps; ++i) {
            double u = (double)i / n_steps;
            worst = std::min(worst, min_clearance(pose_interp(a, b, u), worst));
            if (t_max > 1e-6 && std::abs(t_lin - t_ang) > 0.01) {
                double t = t_max * u;
                double ul = (t_lin > 1e-8) ? std::min(1.0, t / t_lin) : 1.0;
                double ua = (t_ang > 1e-8) ? std::min(1.0, t / t_ang) : 1.0;
                Pose pu = {a.p + (b.p - a.p) * ul, quat_slerp(a.q, b.q, ua)};
                worst = std::min(worst, min_clearance(pu, worst));
            }
        }
        return worst;
    }

    bool check_infinity_escape(const Pose& pose, double escape_thresh, Vec3* best_dir_out = nullptr, double* best_clr_out = nullptr) const {
        const int N_DIRS = 300;
        const double golden = 3.14159265358979323846 * (3.0 - std::sqrt(5.0));
        double best_ray_clr = -1.0;
        Vec3 best_dir = {0, 0, 1};

        Mat3 R = Mat3::from_quat(pose.q);
        Vec3 bmin = {1e9, 1e9, 1e9}, bmax = {-1e9, -1e9, -1e9};
        for (const auto& ts : top) {
            Vec3 w = R.apply(ts.cx, ts.cy, ts.cz) + pose.p;
            bmin.x = std::min(bmin.x, w.x - ts.r); bmax.x = std::max(bmax.x, w.x + ts.r);
            bmin.y = std::min(bmin.y, w.y - ts.r); bmax.y = std::max(bmax.y, w.y + ts.r);
            bmin.z = std::min(bmin.z, w.z - ts.r); bmax.z = std::max(bmax.z, w.z + ts.r);
        }

        for (int i = 0; i < N_DIRS; ++i) {
            double y = 1.0 - (2.0 * i + 1.0) / N_DIRS;
            double rad = std::sqrt(std::max(0.0, 1.0 - y * y));
            double phi = golden * i;
            Vec3 dir = {std::cos(phi) * rad, y, std::sin(phi) * rad};

            double ray_min = 1.0;
            bool ok = true;
            for (double s = 0.0; s <= 4.5; s += 0.025) {
                Vec3 shift = dir * s;
                if ((bmin.x + shift.x > a_max.x + 0.25 && dir.x >= 0) ||
                    (bmax.x + shift.x < a_min.x - 0.25 && dir.x <= 0) ||
                    (bmin.y + shift.y > a_max.y + 0.25 && dir.y >= 0) ||
                    (bmax.y + shift.y < a_min.y - 0.25 && dir.y <= 0) ||
                    (bmin.z + shift.z > a_max.z + 0.25 && dir.z >= 0) ||
                    (bmax.z + shift.z < a_min.z - 0.25 && dir.z <= 0)) {
                    break;
                }
                Vec3 sp = pose.p + shift;
                double c = 1.0;
                double cut = std::max(escape_thresh, best_ray_clr);
                for (const auto& ts : top) {
                    Vec3 wt = R.apply(ts.cx, ts.cy, ts.cz) + sp;
                    double dt = eval_sdf(wt.x, wt.y, wt.z);
                    if (dt - ts.r >= cut) continue;
                    int m_end = ts.start + ts.count;
                    for (int mi = ts.start; mi < m_end; ++mi) {
                        const auto& ms = mid[mi];
                        Vec3 wm = R.apply(ms.cx, ms.cy, ms.cz) + sp;
                        double dm = eval_sdf(wm.x, wm.y, wm.z);
                        if (dm - ms.r >= cut) continue;
                        if (dm < escape_thresh) { ok = false; break; }
                        int l_end = ms.start + ms.count;
                        for (int li = ms.start; li < l_end; li += 2) {
                            const auto& lf = leaves[li];
                            Vec3 wl = R.apply(lf.x, lf.y, lf.z) + sp;
                            double dl = eval_sdf(wl.x, wl.y, wl.z);
                            if (dl < escape_thresh) { ok = false; break; }
                            if (dl < c) c = dl;
                        }
                        if (!ok) break;
                    }
                    if (!ok) break;
                }
                if (!ok) break;
                if (c < ray_min) ray_min = c;
            }
            if (ok && ray_min > best_ray_clr) {
                best_ray_clr = ray_min;
                best_dir = dir;
            }
        }
        if (best_dir_out) *best_dir_out = best_dir;
        if (best_clr_out) *best_clr_out = best_ray_clr;
        return best_ray_clr >= escape_thresh;
    }
};

struct Node {
    Pose pose;
    int parent;
    double radius;
};

int nearest_node(const std::vector<Node>& tree, const Pose& target) {
    int best = 0;
    double best_d = 1e18;
    int n = (int)tree.size();
    for (int i = 0; i < n; ++i) {
        double d = pose_dist(tree[i].pose, target);
        if (d < best_d) {
            best_d = d;
            best = i;
        }
    }
    return best;
}

int main() {
    Scene scene;
    scene.load("/app/planner_data.bin");

    Pose start_pose = {{1.2, 0.36, 0.28}, {1.0, 0.0, 0.0, 0.0}};
    Pose goal_pose  = {{1.2, 0.90, 1.35}, {1.0, 0.0, 0.0, 0.0}};

    std::printf("Start clearance: %.5f m\n", scene.min_clearance(start_pose, 0.5));
    std::printf("Goal  clearance: %.5f m\n", scene.min_clearance(goal_pose, 1.0));
    std::fflush(stdout);

    auto t_begin = std::chrono::steady_clock::now();
    std::atomic<bool> solved{false};
    std::mutex sol_mtx;
    std::vector<Pose> best_raw_path;
    double best_path_clr = -1.0;

    #pragma omp parallel num_threads(10)
    {
        int tid = omp_get_thread_num();
        double req_clr = 0.0035 + 0.0005 * (tid % 6); // 3.5mm .. 6.0mm (+1.2mm fast stride margin = 4.7..7.2mm!)
        std::mt19937_64 rng(9001 + tid * 104729);
        std::uniform_real_distribution<double> u01(0.0, 1.0);
        std::normal_distribution<double> gauss(0.0, 1.0);

        auto sample_quat = [&]() -> Quat {
            Quat q = {gauss(rng), gauss(rng), gauss(rng), gauss(rng)};
            return q.normalized();
        };

        auto sample_pose = [&]() -> Pose {
            double r = u01(rng);
            if (r < 0.45) {
                // Focus around the alpha loops & short-leg crossover region!
                return {
                    {-0.1 + u01(rng) * 2.2, -0.1 + u01(rng) * 2.1, -0.2 + u01(rng) * 1.3},
                    sample_quat()
                };
            } else if (r < 0.85) {
                return {
                    {-0.5 + u01(rng) * 3.1, -0.5 + u01(rng) * 2.6, -0.5 + u01(rng) * 1.9},
                    sample_quat()
                };
            } else {
                return {
                    {-0.7 + u01(rng) * 3.8, -0.7 + u01(rng) * 3.6, -0.7 + u01(rng) * 2.6},
                    sample_quat()
                };
            }
        };

        std::vector<Node> treeA, treeB;
        treeA.reserve(50000);
        treeB.reserve(50000);
        treeA.push_back({start_pose, -1, 1e9});
        treeB.push_back({goal_pose, -1, 1e9});
        bool swapped = false;

        const double STEP_LEN = 0.11;
        const double DD_RADIUS = 1.65;

        for (int iter = 0; iter < 500000 && !solved.load(std::memory_order_relaxed); ++iter) {
            Pose q_rand = sample_pose();
            int near_idx = nearest_node(treeA, q_rand);
            if (pose_dist(treeA[near_idx].pose, q_rand) > treeA[near_idx].radius) {
                continue;
            }

            int cur_idx = near_idx;
            int added = 0;
            for (int step = 0; step < 12; ++step) {
                const Pose& from = treeA[cur_idx].pose;
                double d = pose_dist(from, q_rand);
                if (d < 1e-4) break;
                double frac = std::min(1.0, STEP_LEN / d);
                Pose cand = pose_interp(from, q_rand, frac);
                if (!scene.is_valid(cand, req_clr, 8)) {
                    Pose ret = cand;
                    if (!scene.retract(ret, req_clr + 0.001, 4, 8) ||
                        pose_dist(from, ret) > STEP_LEN * 2.0) {
                        treeA[cur_idx].radius = DD_RADIUS;
                        break;
                    }
                    cand = ret;
                    // After retraction, bridge toward q_rand only 1 step
                    frac = 1.0;
                }
                if (!scene.valid_edge_fast(from, cand, req_clr)) {
                    treeA[cur_idx].radius = DD_RADIUS;
                    break;
                }
                treeA.push_back({cand, cur_idx, 1e9});
                cur_idx = (int)treeA.size() - 1;
                added++;
                if (frac >= 0.999) break;
            }

            if (added > 0) {
                const Pose& target = treeA[cur_idx].pose;
                int b_idx = nearest_node(treeB, target);
                for (int cstep = 0; cstep < 40; ++cstep) {
                    const Pose& fromB = treeB[b_idx].pose;
                    double d = pose_dist(fromB, target);
                    if (d <= STEP_LEN * 1.4) {
                        if (scene.valid_edge_exact(fromB, target, 0.0025)) {
                            std::vector<Pose> pA, pB;
                            for (int k = cur_idx; k != -1; k = treeA[k].parent) pA.push_back(treeA[k].pose);
                            std::reverse(pA.begin(), pA.end());
                            for (int k = b_idx; k != -1; k = treeB[k].parent) pB.push_back(treeB[k].pose);
                            std::vector<Pose> full;
                            if (!swapped) {
                                full = pA;
                                full.insert(full.end(), pB.begin(), pB.end());
                            } else {
                                std::reverse(pB.begin(), pB.end());
                                std::reverse(pA.begin(), pA.end());
                                full = pB;
                                full.insert(full.end(), pA.begin(), pA.end());
                            }
                            double min_c = 1.0;
                            for (size_t i = 0; i + 1 < full.size(); ++i) {
                                min_c = std::min(min_c, scene.edge_min_clearance(full[i], full[i + 1]));
                            }
                            if (min_c >= 0.0020) {
                                auto dt_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                                    std::chrono::steady_clock::now() - t_begin).count();
                                std::lock_guard<std::mutex> lk(sol_mtx);
                                std::printf("[Thread %d] SOLVED in %lld ms! iter=%d, treeA=%zu, treeB=%zu, raw_nodes=%zu, exact_min_clr=%.5f m\n",
                                            tid, (long long)dt_ms, iter, treeA.size(), treeB.size(), full.size(), min_c);
                                std::fflush(stdout);
                                if (min_c > best_path_clr) {
                                    best_path_clr = min_c;
                                    best_raw_path = full;
                                }
                                solved.store(true);
                            }
                        }
                        break;
                    }
                    double frac = STEP_LEN / d;
                    Pose candB = pose_interp(fromB, target, frac);
                    if (!scene.is_valid(candB, req_clr, 8)) {
                        Pose retB = candB;
                        if (!scene.retract(retB, req_clr + 0.001, 3, 8) ||
                            pose_dist(fromB, retB) > STEP_LEN * 2.0) {
                            treeB[b_idx].radius = DD_RADIUS;
                            break;
                        }
                        candB = retB;
                    }
                    if (!scene.valid_edge_fast(fromB, candB, req_clr)) {
                        treeB[b_idx].radius = DD_RADIUS;
                        break;
                    }
                    treeB.push_back({candB, b_idx, 1e9});
                    b_idx = (int)treeB.size() - 1;
                }
            }

            if (treeA.size() > treeB.size()) {
                std::swap(treeA, treeB);
                swapped = !swapped;
            }
            if (tid == 0 && iter % 5000 == 0 && iter > 0) {
                auto dt_s = std::chrono::duration_cast<std::chrono::milliseconds>(
                    std::chrono::steady_clock::now() - t_begin).count() / 1000.0;
                std::printf("[Progress %.1fs] iter=%d, treeA=%zu, treeB=%zu\n", dt_s, iter, treeA.size(), treeB.size());
                std::fflush(stdout);
            }
        }
    }

    if (best_raw_path.empty()) {
        std::printf("FAILED to find path within iteration limit!\n");
        return 1;
    }

    // 1. Subdivide raw path finely (<= 0.04m / 0.08 rad)
    std::vector<Pose> path;
    path.push_back(best_raw_path[0]);
    for (size_t i = 0; i + 1 < best_raw_path.size(); ++i) {
        double dp = (best_raw_path[i + 1].p - best_raw_path[i].p).norm();
        double dq = quat_angle(best_raw_path[i].q, best_raw_path[i + 1].q);
        int n_sub = std::max({1, (int)std::ceil(dp / 0.04), (int)std::ceil(dq / 0.08)});
        for (int s = 1; s <= n_sub; ++s) {
            path.push_back(pose_interp(best_raw_path[i], best_raw_path[i + 1], (double)s / n_sub));
        }
    }

    auto compute_bottleneck = [&](const std::vector<Pose>& pth) {
        double mc = 1.0;
        for (size_t i = 0; i + 1 < pth.size(); ++i) {
            mc = std::min(mc, scene.edge_min_clearance(pth[i], pth[i + 1]));
        }
        return mc;
    };

    double init_bn = compute_bottleneck(path);
    std::printf("Initial subdivided path: %zu waypoints, bottleneck clearance = %.5f m\n", path.size(), init_bn);

    // 2. Polish clearance + smooth path (25 passes using full stride=1!)
    for (int pass = 0; pass < 25; ++pass) {
        for (size_t i = 1; i + 1 < path.size(); ++i) {
            double old_c = std::min(scene.edge_min_clearance(path[i - 1], path[i]),
                                    scene.edge_min_clearance(path[i], path[i + 1]));
            Pose mid_p = pose_interp(path[i - 1], path[i + 1], 0.5);
            Pose cand = pose_interp(path[i], mid_p, 0.35);
            double target_push = std::min(0.030, old_c + 0.008);
            scene.retract(cand, target_push, 3, 2);
            double new_c = std::min(scene.edge_min_clearance(path[i - 1], cand),
                                    scene.edge_min_clearance(cand, path[i + 1]));
            if (new_c >= std::min(0.022, old_c)) {
                path[i] = cand;
            } else if (old_c < 0.022) {
                Pose push_p = path[i];
                if (scene.retract(push_p, old_c + 0.005, 3, 2)) {
                    double pc = std::min(scene.edge_min_clearance(path[i - 1], push_p),
                                         scene.edge_min_clearance(push_p, path[i + 1]));
                    if (pc > old_c) path[i] = push_p;
                }
            }
        }
    }
    double polished_bn = compute_bottleneck(path);
    std::printf("After clearance polishing: bottleneck clearance = %.5f m\n", polished_bn);

    // 3. Find earliest waypoint with wide straight-line infinity escape!
    size_t first_esc_6cm = path.size() - 1;
    bool found_2cm = false;
    for (size_t i = 0; i < path.size(); ++i) {
        Vec3 dir; double rclr;
        if (scene.check_infinity_escape(path[i], 0.020, &dir, &rclr)) {
            if (!found_2cm) {
                found_2cm = true;
                std::printf("First 20mm straight-line escape at waypoint %zu/%zu (ray_clr=%.4f m, dir=[%.3f, %.3f, %.3f])\n",
                            i, path.size() - 1, rclr, dir.x, dir.y, dir.z);
            }
            if (rclr >= 0.065) {
                first_esc_6cm = i;
                std::printf("Wide 65mm straight-line escape at waypoint %zu/%zu (ray_clr=%.4f m, dir=[%.3f, %.3f, %.3f])\n",
                            i, path.size() - 1, rclr, dir.x, dir.y, dir.z);
                break;
            }
        }
    }
    if (first_esc_6cm + 1 < path.size()) {
        path.resize(first_esc_6cm + 1);
    }

    // 4. Shortcut path preserving clearance >= keep_clr
    double keep_clr = std::min(0.018, polished_bn - 0.0005);
    std::mt19937_64 srng(42);
    for (int it = 0; it < 800 && path.size() > 2; ++it) {
        size_t i = srng() % (path.size() - 1);
        size_t j = i + 2 + (srng() % std::max<size_t>(1, path.size() - i - 1));
        if (j >= path.size()) continue;
        if (scene.valid_edge_exact(path[i], path[j], keep_clr) &&
            scene.edge_min_clearance(path[i], path[j]) >= keep_clr) {
            std::vector<Pose> next_p;
            for (size_t k = 0; k <= i; ++k) next_p.push_back(path[k]);
            double dp = (path[j].p - path[i].p).norm();
            double dq = quat_angle(path[i].q, path[j].q);
            int n_sub = std::max({1, (int)std::ceil(dp / 0.045), (int)std::ceil(dq / 0.09)});
            for (int s = 1; s < n_sub; ++s) {
                next_p.push_back(pose_interp(path[i], path[j], (double)s / n_sub));
            }
            for (size_t k = j; k < path.size(); ++k) next_p.push_back(path[k]);
            path = std::move(next_p);
        }
    }

    // 5. Discretize into legal `move` steps (dp <= 0.095 m, dq <= 0.190 rad) via DP!
    const double MAX_DP = 0.095;
    const double MAX_DQ = 0.190;
    size_t N = path.size();
    std::vector<int> dp_cost(N, 1e9);
    std::vector<int> dp_prev(N, -1);
    dp_cost[0] = 0;
    for (size_t i = 0; i < N; ++i) {
        if (dp_cost[i] >= 1e8) continue;
        for (size_t j = i + 1; j < N; ++j) {
            double d_lin = (path[j].p - path[i].p).norm();
            double d_ang = quat_angle(path[i].q, path[j].q);
            if ((d_lin > MAX_DP || d_ang > MAX_DQ) && j > i + 1) continue;
            if (d_lin <= MAX_DP && d_ang <= MAX_DQ) {
                if (dp_cost[i] + 1 < dp_cost[j]) {
                    if (scene.valid_edge_exact(path[i], path[j], keep_clr) &&
                        scene.edge_min_clearance(path[i], path[j]) >= keep_clr) {
                        dp_cost[j] = dp_cost[i] + 1;
                        dp_prev[j] = (int)i;
                    }
                }
            }
        }
        if (i + 1 < N && dp_cost[i + 1] >= 1e8) {
            dp_cost[i + 1] = dp_cost[i] + 1;
            dp_prev[i + 1] = (int)i;
        }
    }

    std::vector<Pose> move_plan;
    for (int cur = (int)N - 1; cur != -1; cur = dp_prev[cur]) {
        move_plan.push_back(path[cur]);
    }
    std::reverse(move_plan.begin(), move_plan.end());

    double final_bn = compute_bottleneck(move_plan);
    std::printf("\n=== FINAL MOVE PLAN: %zu move steps (+1 grab = %zu total actions / 198), bottleneck clearance = %.5f m ===\n",
                move_plan.size() - 1, move_plan.size(), final_bn);

    FILE* jf = std::fopen("/app/planned_path.json", "w");
    std::fprintf(jf, "{\n  \"bottleneck_clearance_m\": %.6f,\n  \"num_moves\": %zu,\n  \"waypoints\": [\n",
                 final_bn, move_plan.size() - 1);
    for (size_t i = 0; i < move_plan.size(); ++i) {
        const auto& wp = move_plan[i];
        double edge_c = (i == 0) ? scene.min_clearance(wp, 0.5) : scene.edge_min_clearance(move_plan[i - 1], wp);
        double d_lin = (i == 0) ? 0.0 : (wp.p - move_plan[i - 1].p).norm();
        double d_ang = (i == 0) ? 0.0 : quat_angle(move_plan[i - 1].q, wp.q);
        Vec3 edir = {0, 0, 1}; double eclr = -1.0;
        scene.check_infinity_escape(wp, 0.005, &edir, &eclr);
        std::printf("  Step %2zu: pos=[%7.4f, %7.4f, %7.4f] quat=[%7.4f, %7.4f, %7.4f, %7.4f] | dp=%.4f dq=%.4f | edge_clr=%.4fm | esc_clr=%.4fm\n",
                    i, wp.p.x, wp.p.y, wp.p.z, wp.q.w, wp.q.x, wp.q.y, wp.q.z, d_lin, d_ang, edge_c, eclr);
        std::fprintf(jf, "    {\"pos\": [%.7f, %.7f, %.7f], \"quat\": [%.7f, %.7f, %.7f, %.7f], \"edge_clr\": %.6f, \"esc_clr\": %.6f}%s\n",
                     wp.p.x, wp.p.y, wp.p.z, wp.q.w, wp.q.x, wp.q.y, wp.q.z, edge_c, eclr,
                     (i + 1 < move_plan.size()) ? "," : "");
    }
    std::fprintf(jf, "  ]\n}\n");
    std::fclose(jf);
    std::printf("Saved /app/planned_path.json!\n");
    return 0;
}

