#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <mutex>
#include <omp.h>
#include <random>
#include <vector>

struct Vec3 {
    double x, y, z;
    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(double s) const { return {x * s, y * s, z * s}; }
    double dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
    Vec3 cross(const Vec3& o) const {
        return {y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x};
    }
    double norm2() const { return x * x + y * y + z * z; }
    double norm() const { return std::sqrt(norm2()); }
};

struct Quat {
    double w, x, y, z;
    Quat normalized() const {
        double n = std::sqrt(w * w + x * x + y * y + z * z);
        if (n < 1e-12) return {1, 0, 0, 0};
        if (w < 0) n = -n;
        return {w / n, x / n, y / n, z / n};
    }
    Quat operator*(const Quat& o) const {
        return {
            w * o.w - x * o.x - y * o.y - z * o.z,
            w * o.x + x * o.w + y * o.z - z * o.y,
            w * o.y - x * o.z + y * o.w + z * o.x,
            w * o.z + x * o.y - y * o.x + z * o.w
        };
    }
};

struct Mat3 {
    double m[9];
    static Mat3 from_quat(const Quat& q) {
        double xx = q.x * q.x, yy = q.y * q.y, zz = q.z * q.z;
        double xy = q.x * q.y, xz = q.x * q.z, yz = q.y * q.z;
        double wx = q.w * q.x, wy = q.w * q.y, wz = q.w * q.z;
        return {{
            1.0 - 2.0 * (yy + zz), 2.0 * (xy - wz),       2.0 * (xz + wy),
            2.0 * (xy + wz),       1.0 - 2.0 * (xx + zz), 2.0 * (yz - wx),
            2.0 * (xz - wy),       2.0 * (yz + wx),       1.0 - 2.0 * (xx + yy)
        }};
    }
    Vec3 apply(double px, double py, double pz) const {
        return {
            m[0] * px + m[1] * py + m[2] * pz,
            m[3] * px + m[4] * py + m[5] * pz,
            m[6] * px + m[7] * py + m[8] * pz
        };
    }
};

inline double quat_angle(const Quat& a, const Quat& b) {
    double d = std::abs(a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z);
    if (d >= 1.0) return 0.0;
    return 2.0 * std::acos(d);
}

Quat quat_slerp(const Quat& a, Quat b, double t) {
    double d = a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
    if (d < 0.0) {
        b = {-b.w, -b.x, -b.y, -b.z};
        d = -d;
    }
    if (d > 0.9995) {
        Quat r = {a.w + t * (b.w - a.w), a.x + t * (b.x - a.x),
                  a.y + t * (b.y - a.y), a.z + t * (b.z - a.z)};
        return r.normalized();
    }
    double theta = std::acos(d);
    double st = std::sin(theta);
    double wa = std::sin((1.0 - t) * theta) / st;
    double wb = std::sin(t * theta) / st;
    return Quat{wa * a.w + wb * b.w, wa * a.x + wb * b.x,
                wa * a.y + wb * b.y, wa * a.z + wb * b.z}.normalized();
}

Quat quat_from_rotvec(const Vec3& rv) {
    double ang = rv.norm();
    if (ang < 1e-10) return Quat{1.0, 0.5 * rv.x, 0.5 * rv.y, 0.5 * rv.z}.normalized();
    double s = std::sin(0.5 * ang) / ang;
    return Quat{std::cos(0.5 * ang), rv.x * s, rv.y * s, rv.z * s}.normalized();
}

struct Pose {
    Vec3 p;
    Quat q;
};

Pose pose_interp(const Pose& a, const Pose& b, double t) {
    return {a.p + (b.p - a.p) * t, quat_slerp(a.q, b.q, t)};
}

inline double pose_dist(const Pose& a, const Pose& b) {
    double dx = a.p.x - b.p.x, dy = a.p.y - b.p.y, dz = a.p.z - b.p.z;
    double dp = std::sqrt(dx * dx + dy * dy + dz * dz);
    double dot = std::abs(a.q.w * b.q.w + a.q.x * b.q.x + a.q.y * b.q.y + a.q.z * b.q.z);
    double dq = (dot >= 1.0) ? 0.0 : 2.828427 * std::sqrt(1.0 - dot);
    return dp + 0.65 * dq;
}

struct SphereNode {
    float cx, cy, cz, r;
    int32_t start, count;
};

struct LeafPt {
    float x, y, z;
};

struct Scene {
    uint32_t nx, ny, nz;
    double h, inv_h;
    Vec3 origin, a_min, a_max;
    std::vector<float> sdf;

    // Coarse 1cm L3-cache-friendly SDF (28 MB!) for ultra-fast exploration
    uint32_t cnx, cny, cnz;
    double ch, cinv_h;
    std::vector<float> csdf;

    std::vector<SphereNode> top;
    std::vector<SphereNode> mid;
    std::vector<LeafPt> leaves;

    // Fast coarse leaf list under `top` (max 16 representative points per top sphere = ~1500 pts total!)
    std::vector<SphereNode> fast_top;
    std::vector<LeafPt> fast_leaves;

    void load(const char* path) {
        FILE* f = std::fopen(path, "rb");
        if (!f) { std::perror("fopen"); std::exit(1); }
        uint32_t magic;
        if (std::fread(&magic, 4, 1, f) != 1 || magic != 0x414C5048) std::exit(1);
        if (std::fread(&nx, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&ny, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&nz, 4, 1, f) != 1) std::exit(1);
        double hdr[10];
        if (std::fread(hdr, sizeof(double), 10, f) != 10) std::exit(1);
        h = hdr[0]; inv_h = 1.0 / h;
        origin = {hdr[1], hdr[2], hdr[3]};
        a_min = {hdr[4], hdr[5], hdr[6]};
        a_max = {hdr[7], hdr[8], hdr[9]};
        uint32_t n_top, n_mid, n_leaves;
        if (std::fread(&n_top, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&n_mid, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&n_leaves, 4, 1, f) != 1) std::exit(1);
        size_t n_vox = (size_t)nx * ny * nz;
        sdf.resize(n_vox);
        if (std::fread(sdf.data(), sizeof(float), n_vox, f) != n_vox) std::exit(1);
        top.resize(n_top);
        if (std::fread(top.data(), sizeof(SphereNode), n_top, f) != n_top) std::exit(1);
        mid.resize(n_mid);
        if (std::fread(mid.data(), sizeof(SphereNode), n_mid, f) != n_mid) std::exit(1);
        leaves.resize(n_leaves);
        if (std::fread(leaves.data(), sizeof(LeafPt), n_leaves, f) != n_leaves) std::exit(1);
        std::fclose(f);

        // Build 2x downsampled L3-cached SDF (10mm grid, 28 MB!)
        cnx = (nx + 1) / 2; cny = (ny + 1) / 2; cnz = (nz + 1) / 2;
        ch = h * 2.0; cinv_h = 1.0 / ch;
        csdf.resize((size_t)cnx * cny * cnz);
        for (uint32_t i = 0; i < cnx; ++i) {
            uint32_t si = std::min(nx - 1, i * 2);
            for (uint32_t j = 0; j < cny; ++j) {
                uint32_t sj = std::min(ny - 1, j * 2);
                for (uint32_t k = 0; k < cnz; ++k) {
                    uint32_t sk = std::min(nz - 1, k * 2);
                    csdf[((size_t)i * cny + j) * cnz + k] = sdf[((size_t)si * ny + sj) * nz + sk];
                }
            }
        }

        // Build fast_top + fast_leaves (~2 pts per mid-sphere = ~2,300 pts total, contiguous in L1 cache!)
        fast_top = top;
        for (auto& ft : fast_top) {
            int f_start = (int)fast_leaves.size();
            for (int mi = ft.start; mi < ft.start + ft.count; ++mi) {
                const auto& ms = mid[mi];
                // Mid-sphere center + 1 farthest leaf
                fast_leaves.push_back({ms.cx, ms.cy, ms.cz});
                if (ms.count > 0) {
                    fast_leaves.push_back(leaves[ms.start]);
                    if (ms.count > 2) fast_leaves.push_back(leaves[ms.start + ms.count / 2]);
                }
            }
            ft.start = f_start;
            ft.count = (int)fast_leaves.size() - f_start;
        }
        std::printf("Loaded Scene: %ux%ux%u SDF (coarse %ux%ux%u), %zu fast_leaves, %u exact leaves\n",
                    nx, ny, nz, cnx, cny, cnz, fast_leaves.size(), n_leaves);
    }

    inline double eval_csdf(double wx, double wy, double wz) const {
        double fx = (wx - origin.x) * cinv_h;
        double fy = (wy - origin.y) * cinv_h;
        double fz = (wz - origin.z) * cinv_h;
        if (fx >= 0.0 && fy >= 0.0 && fz >= 0.0) {
            int ix = (int)fx, iy = (int)fy, iz = (int)fz;
            if (ix < (int)cnx - 1 && iy < (int)cny - 1 && iz < (int)cnz - 1) {
                double tx = fx - ix, ty = fy - iy, tz = fz - iz;
                size_t sx = (size_t)cny * cnz, sy = (size_t)cnz;
                const float* p = csdf.data() + (size_t)ix * sx + (size_t)iy * sy + (size_t)iz;
                double c00 = p[0] + tx * (p[sx] - p[0]);
                double c01 = p[1] + tx * (p[sx + 1] - p[1]);
                double c10 = p[sy] + tx * (p[sx + sy] - p[sy]);
                double c11 = p[sy + 1] + tx * (p[sx + sy + 1] - p[sy + 1]);
                return (c00 + ty * (c10 - c00)) + tz * ((c01 + ty * (c11 - c01)) - (c00 + ty * (c10 - c00)));
            }
        }
        double dx = std::max({0.0, a_min.x - wx, wx - a_max.x});
        double dy = std::max({0.0, a_min.y - wy, wy - a_max.y});
        double dz = std::max({0.0, a_min.z - wz, wz - a_max.z});
        return std::sqrt(dx * dx + dy * dy + dz * dz);
    }

    inline double eval_sdf(double wx, double wy, double wz) const {
        double fx = (wx - origin.x) * inv_h;
        double fy = (wy - origin.y) * inv_h;
        double fz = (wz - origin.z) * inv_h;
        if (fx >= 0.0 && fy >= 0.0 && fz >= 0.0) {
            int ix = (int)fx, iy = (int)fy, iz = (int)fz;
            if (ix < (int)nx - 1 && iy < (int)ny - 1 && iz < (int)nz - 1) {
                double tx = fx - ix, ty = fy - iy, tz = fz - iz;
                size_t sx = (size_t)ny * nz, sy = (size_t)nz;
                const float* p = sdf.data() + (size_t)ix * sx + (size_t)iy * sy + (size_t)iz;
                double c00 = p[0] + tx * (p[sx] - p[0]);
                double c01 = p[1] + tx * (p[sx + 1] - p[1]);
                double c10 = p[sy] + tx * (p[sx + sy] - p[sy]);
                double c11 = p[sy + 1] + tx * (p[sx + sy + 1] - p[sy + 1]);
                return (c00 + ty * (c10 - c00)) + tz * ((c01 + ty * (c11 - c01)) - (c00 + ty * (c10 - c00)));
            }
        }
        double dx = std::max({0.0, a_min.x - wx, wx - a_max.x});
        double dy = std::max({0.0, a_min.y - wy, wy - a_max.y});
        double dz = std::max({0.0, a_min.z - wz, wz - a_max.z});
        return std::sqrt(dx * dx + dy * dy + dz * dz);
    }

    inline Vec3 eval_cgrad(double wx, double wy, double wz) const {
        double eps = 0.010;
        Vec3 g = {
            eval_csdf(wx + eps, wy, wz) - eval_csdf(wx - eps, wy, wz),
            eval_csdf(wx, wy + eps, wz) - eval_csdf(wx, wy - eps, wz),
            eval_csdf(wx, wy, wz + eps) - eval_csdf(wx, wy, wz - eps)
        };
        double n = g.norm();
        return (n < 1e-9) ? Vec3{0, 0, 1} : (g * (1.0 / n));
    }

    inline bool in_workspace(const Pose& pose) const {
        return !(pose.p.x < -0.74 || pose.p.x > 3.14 ||
                 pose.p.y < -0.74 || pose.p.y > 3.14 ||
                 pose.p.z < -0.74 || pose.p.z > 3.14);
    }

    // Ultra-fast L3-cached pose check (~0.3 us!)
    inline bool is_valid_fast(const Pose& pose, double thresh) const {
        if (!in_workspace(pose)) return false;
        Mat3 R = Mat3::from_quat(pose.q);
        double eff = thresh + 0.0020; // 2mm safety buffer for coarse samples
        for (const auto& ft : fast_top) {
            Vec3 wt = R.apply(ft.cx, ft.cy, ft.cz) + pose.p;
            double dt = eval_csdf(wt.x, wt.y, wt.z);
            if (dt - ft.r >= eff) continue;
            if (dt < -0.05) return false;
            int end = ft.start + ft.count;
            for (int i = ft.start; i < end; ++i) {
                const auto& lf = fast_leaves[i];
                Vec3 wl = R.apply(lf.x, lf.y, lf.z) + pose.p;
                if (eval_csdf(wl.x, wl.y, wl.z) < eff) return false;
            }
        }
        return true;
    }

    inline double fast_clearance(const Pose& pose, double cap = 0.20) const {
        if (!in_workspace(pose)) return -1.0;
        Mat3 R = Mat3::from_quat(pose.q);
        double best = cap;
        for (const auto& ft : fast_top) {
            Vec3 wt = R.apply(ft.cx, ft.cy, ft.cz) + pose.p;
            double dt = eval_csdf(wt.x, wt.y, wt.z);
            if (dt - ft.r >= best) continue;
            int end = ft.start + ft.count;
            for (int i = ft.start; i < end; ++i) {
                const auto& lf = fast_leaves[i];
                Vec3 wl = R.apply(lf.x, lf.y, lf.z) + pose.p;
                double d = eval_csdf(wl.x, wl.y, wl.z);
                if (d < best) best = d;
            }
        }
        return best;
    }

    bool retract_fast(Pose& pose, double thresh, int max_iters = 5) const {
        double eff = thresh + 0.0020;
        for (int it = 0; it < max_iters; ++it) {
            if (!in_workspace(pose)) return false;
            Mat3 R = Mat3::from_quat(pose.q);
            double margin = eff + 0.018;
            Vec3 force = {0, 0, 0}, torque = {0, 0, 0};
            double w_sum = 0.0, worst_d = 1e9;

            for (const auto& ft : fast_top) {
                Vec3 wt = R.apply(ft.cx, ft.cy, ft.cz) + pose.p;
                double dt = eval_csdf(wt.x, wt.y, wt.z);
                if (dt - ft.r >= margin) continue;
                if (dt < -0.05) return false;
                int end = ft.start + ft.count;
                double min_t = 1e9;
                Vec3 worst_rel = {0, 0, 0};
                for (int i = ft.start; i < end; ++i) {
                    const auto& lf = fast_leaves[i];
                    Vec3 rel = R.apply(lf.x, lf.y, lf.z);
                    Vec3 wl = rel + pose.p;
                    double dl = eval_csdf(wl.x, wl.y, wl.z);
                    if (dl < min_t) { min_t = dl; worst_rel = rel; }
                }
                if (min_t < worst_d) worst_d = min_t;
                if (min_t < margin) {
                    Vec3 wl = worst_rel + pose.p;
                    Vec3 g = eval_cgrad(wl.x, wl.y, wl.z);
                    double pen = margin - min_t;
                    double w = pen * pen + 1e-4;
                    force = force + g * w;
                    torque = torque + worst_rel.cross(g) * w;
                    w_sum += w;
                }
            }
            if (worst_d >= eff) return true;
            if (worst_d < -0.035 || w_sum < 1e-9) return false;
            force = force * (1.0 / w_sum);
            torque = torque * (1.0 / w_sum);
            double fn = force.norm(), tn = torque.norm();
            double need = std::max(0.004, (eff - worst_d) + 0.003);
            if (fn > 1e-6) pose.p = pose.p + force * (std::min(0.020, need) / fn);
            if (tn > 1e-6) {
                Quat dq = quat_from_rotvec(torque * (std::min(0.035, need * 1.4) / tn));
                pose.q = (dq * pose.q).normalized();
            }
        }
        return is_valid_fast(pose, thresh);
    }

    bool valid_edge_fast(const Pose& a, const Pose& b, double thresh) const {
        double dp = (b.p - a.p).norm();
        double dq = quat_angle(a.q, b.q);
        int ns = std::max({2, (int)std::ceil(dp / 0.015), (int)std::ceil(dq / 0.030)});
        if (!is_valid_fast(pose_interp(a, b, 0.5), thresh)) return false;
        for (int i = 1; i <= ns; ++i) {
            if (i * 2 == ns) continue;
            if (!is_valid_fast(pose_interp(a, b, (double)i / ns), thresh)) return false;
        }
        return true;
    }

    // Exact 91,875-leaf evaluation for Stage 2 polishing & verification!
    bool is_valid_exact(const Pose& pose, double thresh) const {
        if (!in_workspace(pose)) return false;
        Mat3 R = Mat3::from_quat(pose.q);
        for (const auto& ts : top) {
            Vec3 wt = R.apply(ts.cx, ts.cy, ts.cz) + pose.p;
            double dt = eval_sdf(wt.x, wt.y, wt.z);
            if (dt - ts.r >= thresh) continue;
            int m_end = ts.start + ts.count;
            for (int mi = ts.start; mi < m_end; ++mi) {
                const auto& ms = mid[mi];
                Vec3 wm = R.apply(ms.cx, ms.cy, ms.cz) + pose.p;
                double dm = eval_sdf(wm.x, wm.y, wm.z);
                if (dm - ms.r >= thresh) continue;
                if (dm < thresh) return false;
                int l_end = ms.start + ms.count;
                for (int li = ms.start; li < l_end; ++li) {
                    const auto& lf = leaves[li];
                    Vec3 wl = R.apply(lf.x, lf.y, lf.z) + pose.p;
                    if (eval_sdf(wl.x, wl.y, wl.z) < thresh) return false;
                }
            }
        }
        return true;
    }

    double min_clearance_exact(const Pose& pose, double max_cap = 0.25) const {
        if (!in_workspace(pose)) return -1.0;
        Mat3 R = Mat3::from_quat(pose.q);
        double best = max_cap;
        for (const auto& ts : top) {
            Vec3 wt = R.apply(ts.cx, ts.cy, ts.cz) + pose.p;
            double dt = eval_sdf(wt.x, wt.y, wt.z);
            if (dt - ts.r >= best) continue;
            int m_end = ts.start + ts.count;
            for (int mi = ts.start; mi < m_end; ++mi) {
                const auto& ms = mid[mi];
                Vec3 wm = R.apply(ms.cx, ms.cy, ms.cz) + pose.p;
                double dm = eval_sdf(wm.x, wm.y, wm.z);
                if (dm - ms.r >= best) continue;
                int l_end = ms.start + ms.count;
                for (int li = ms.start; li < l_end; ++li) {
                    const auto& lf = leaves[li];
                    Vec3 wl = R.apply(lf.x, lf.y, lf.z) + pose.p;
                    double dl = eval_sdf(wl.x, wl.y, wl.z);
                    if (dl < best) best = dl;
                }
            }
        }
        return best;
    }

    bool valid_edge_exact(const Pose& a, const Pose& b, double thresh) const {
        double dp = (b.p - a.p).norm();
        double dq = quat_angle(a.q, b.q);
        int ns = std::max({2, (int)std::ceil(dp / 0.006), (int)std::ceil(dq / 0.012)});
        for (int i = 1; i <= ns; ++i) {
            if (!is_valid_exact(pose_interp(a, b, (double)i / ns), thresh)) return false;
        }
        double t_lin = dp / 0.1, t_ang = dq / 0.1, t_max = std::max(t_lin, t_ang);
        if (t_max > 1e-6 && std::abs(t_lin - t_ang) > 0.015) {
            for (int i = 1; i < ns; ++i) {
                double t = t_max * ((double)i / ns);
                double ul = (t_lin > 1e-8) ? std::min(1.0, t / t_lin) : 1.0;
                double ua = (t_ang > 1e-8) ? std::min(1.0, t / t_ang) : 1.0;
                Pose pu = {a.p + (b.p - a.p) * ul, quat_slerp(a.q, b.q, ua)};
                if (!is_valid_exact(pu, thresh)) return false;
            }
        }
        return true;
    }

    double edge_min_clearance_exact(const Pose& a, const Pose& b) const {
        double dp = (b.p - a.p).norm();
        double dq = quat_angle(a.q, b.q);
        int ns = std::max({2, (int)std::ceil(dp / 0.006), (int)std::ceil(dq / 0.012)});
        double worst = 1.0;
        double t_lin = dp / 0.1, t_ang = dq / 0.1, t_max = std::max(t_lin, t_ang);
        for (int i = 0; i <= ns; ++i) {
            double u = (double)i / ns;
            worst = std::min(worst, min_clearance_exact(pose_interp(a, b, u), worst));
            if (t_max > 1e-6 && std::abs(t_lin - t_ang) > 0.015) {
                double t = t_max * u;
                double ul = (t_lin > 1e-8) ? std::min(1.0, t / t_lin) : 1.0;
                double ua = (t_ang > 1e-8) ? std::min(1.0, t / t_ang) : 1.0;
                Pose pu = {a.p + (b.p - a.p) * ul, quat_slerp(a.q, b.q, ua)};
                worst = std::min(worst, min_clearance_exact(pu, worst));
            }
        }
        return worst;
    }

    bool check_infinity_escape(const Pose& pose, double escape_thresh, Vec3* best_dir_out = nullptr, double* best_clr_out = nullptr) const {
        const int N_DIRS = 120;
        const double golden = 3.14159265358979323846 * (3.0 - std::sqrt(5.0));
        double best_ray_clr = -1.0;
        Vec3 best_dir = {0, 0, 1};

        Mat3 R = Mat3::from_quat(pose.q);
        Vec3 bmin = {1e9, 1e9, 1e9}, bmax = {-1e9, -1e9, -1e9};
        for (const auto& ts : top) {
            Vec3 w = R.apply(ts.cx, ts.cy, ts.cz) + pose.p;
            bmin.x = std::min(bmin.x, w.x - ts.r); bmax.x = std::max(bmax.x, w.x + ts.r);
            bmin.y = std::min(bmin.y, w.y - ts.r); bmax.y = std::max(bmax.y, w.y + ts.r);
            bmin.z = std::min(bmin.z, w.z - ts.r); bmax.z = std::max(bmax.z, w.z + ts.r);
        }

        auto eval_ray = [&](const Vec3& dir, bool exact, double req) -> double {
            double rmin = 1.0;
            for (double s = 0.0; s <= 4.2; s += 0.030) {
                Vec3 shift = dir * s;
                if ((bmin.x + shift.x > a_max.x + 0.25 && dir.x >= 0) ||
                    (bmax.x + shift.x < a_min.x - 0.25 && dir.x <= 0) ||
                    (bmin.y + shift.y > a_max.y + 0.25 && dir.y >= 0) ||
                    (bmax.y + shift.y < a_min.y - 0.25 && dir.y <= 0) ||
                    (bmin.z + shift.z > a_max.z + 0.25 && dir.z >= 0) ||
                    (bmax.z + shift.z < a_min.z - 0.25 && dir.z <= 0)) {
                    break;
                }
                Vec3 sp = pose.p + shift;
                if (!exact) {
                    for (const auto& ft : fast_top) {
                        Vec3 wt = R.apply(ft.cx, ft.cy, ft.cz) + sp;
                        double dt = eval_csdf(wt.x, wt.y, wt.z);
                        if (dt - ft.r >= rmin) continue;
                        int end = ft.start + ft.count;
                        for (int k = ft.start; k < end; ++k) {
                            const auto& lf = fast_leaves[k];
                            Vec3 wl = R.apply(lf.x, lf.y, lf.z) + sp;
                            double dl = eval_csdf(wl.x, wl.y, wl.z);
                            if (dl < req) return -1.0;
                            if (dl < rmin) rmin = dl;
                        }
                    }
                } else {
                    for (const auto& ts : top) {
                        Vec3 wt = R.apply(ts.cx, ts.cy, ts.cz) + sp;
                        double dt = eval_sdf(wt.x, wt.y, wt.z);
                        if (dt - ts.r >= rmin) continue;
                        int m_end = ts.start + ts.count;
                        for (int mi = ts.start; mi < m_end; ++mi) {
                            const auto& ms = mid[mi];
                            Vec3 wm = R.apply(ms.cx, ms.cy, ms.cz) + sp;
                            double dm = eval_sdf(wm.x, wm.y, wm.z);
                            if (dm - ms.r >= rmin) continue;
                            if (dm < req) return -1.0;
                            int l_end = ms.start + ms.count;
                            for (int li = ms.start; li < l_end; ++li) {
                                const auto& lf = leaves[li];
                                Vec3 wl = R.apply(lf.x, lf.y, lf.z) + sp;
                                double dl = eval_sdf(wl.x, wl.y, wl.z);
                                if (dl < req) return -1.0;
                                if (dl < rmin) rmin = dl;
                            }
                        }
                    }
                }
            }
            return rmin;
        };

        for (int i = 0; i < N_DIRS; ++i) {
            double y = 1.0 - (2.0 * i + 1.0) / N_DIRS;
            double rad = std::sqrt(std::max(0.0, 1.0 - y * y));
            double phi = golden * i;
            Vec3 dir = {std::cos(phi) * rad, y, std::sin(phi) * rad};
            double cc = eval_ray(dir, false, std::max(escape_thresh + 0.002, best_ray_clr));
            if (cc >= escape_thresh) {
                double ce = eval_ray(dir, true, escape_thresh);
                if (ce > best_ray_clr) { best_ray_clr = ce; best_dir = dir; }
            }
        }
        if (best_dir_out) *best_dir_out = best_dir;
        if (best_clr_out) *best_clr_out = best_ray_clr;
        return best_ray_clr >= escape_thresh;
    }
};

struct RRTNode {
    float px, py, pz, qw, qx, qy, qz;
    int parent;
    float dd_rad;

    Pose to_pose() const { return {{px, py, pz}, {qw, qx, qy, qz}}; }
    static RRTNode from_pose(const Pose& p, int par, float r = 1e9f) {
        return {(float)p.p.x, (float)p.p.y, (float)p.p.z,
                (float)p.q.w, (float)p.q.x, (float)p.q.y, (float)p.q.z, par, r};
    }
};

int nearest_node(const std::vector<RRTNode>& tree, const Pose& t) {
    int best = 0;
    float best_d = 1e18f;
    float tx = (float)t.p.x, ty = (float)t.p.y, tz = (float)t.p.z;
    float tw = (float)t.q.w, qx = (float)t.q.x, qy = (float)t.q.y, qz = (float)t.q.z;
    int n = (int)tree.size();
    const RRTNode* ptr = tree.data();
    for (int i = 0; i < n; ++i) {
        float dx = ptr[i].px - tx, dy = ptr[i].py - ty, dz = ptr[i].pz - tz;
        float dp2 = dx * dx + dy * dy + dz * dz;
        if (dp2 >= best_d * best_d) continue;
        float dot = std::abs(ptr[i].qw * tw + ptr[i].qx * qx + ptr[i].qy * qy + ptr[i].qz * qz);
        float dq = (dot >= 1.0f) ? 0.0f : 2.828427f * std::sqrt(1.0f - dot);
        float d = std::sqrt(dp2) + 0.65f * dq;
        if (d < best_d) { best_d = d; best = i; }
    }
    return best;
}

int main() {
    Scene scene;
    scene.load("/app/planner_data.bin");

    Pose start_pose = {{1.2, 0.36, 0.28}, {1.0, 0.0, 0.0, 0.0}};
    Pose goal_pose  = {{1.0, 0.90, 1.30}, {1.0, 0.0, 0.0, 0.0}};

    std::printf("Start clearance: exact=%.5f m, fast=%.5f m\n",
                scene.min_clearance_exact(start_pose, 0.5), scene.fast_clearance(start_pose, 0.5));
    std::fflush(stdout);

    auto t_begin = std::chrono::steady_clock::now();
    std::atomic<bool> solved{false};
    std::mutex sol_mtx;
    std::vector<Pose> best_raw_path;
    double best_path_clr = -1.0;

    // 10-thread Balanced OB-BiRRT-Connect!
    #pragma omp parallel num_threads(10)
    {
        int tid = omp_get_thread_num();
        double req_clr = 0.0020 + 0.0005 * (tid % 6); // +2mm fast buffer => 4.0mm .. 6.5mm!
        std::mt19937_64 rng(314159 + tid * 987654323ULL);
        std::uniform_real_distribution<double> u01(0.0, 1.0);
        std::normal_distribution<double> gauss(0.0, 1.0);

        auto sample_quat = [&]() -> Quat {
            return Quat{gauss(rng), gauss(rng), gauss(rng), gauss(rng)}.normalized();
        };

        // Obstacle-Based Narrow-Passage Sampler + Tight Box Sampler!
        auto sample_target = [&]() -> Pose {
            double r = u01(rng);
            if (r < 0.55) {
                // OB-Sample: generate pose near crossover/loops and retract onto narrow-passage medial axis!
                for (int tries = 0; tries < 8; ++tries) {
                    Pose p = {
                        {0.0 + u01(rng) * 2.1, -0.1 + u01(rng) * 1.85, -0.25 + u01(rng) * 1.15},
                        sample_quat()
                    };
                    double c = scene.fast_clearance(p, 0.06);
                    if (c > -0.030 && c < 0.035) {
                        if (scene.retract_fast(p, req_clr + 0.001, 5)) return p;
                    }
                }
            }
            if (r < 0.85) {
                return {
                    {-0.2 + u01(rng) * 2.5, -0.2 + u01(rng) * 2.1, -0.3 + u01(rng) * 1.6},
                    sample_quat()
                };
            }
            return {
                {-0.65 + u01(rng) * 3.6, -0.65 + u01(rng) * 3.1, -0.6 + u01(rng) * 2.2},
                sample_quat()
            };
        };

        std::vector<RRTNode> treeA, treeB;
        treeA.reserve(35000);
        treeB.reserve(35000);
        treeA.push_back(RRTNode::from_pose(start_pose, -1));
        treeB.push_back(RRTNode::from_pose(goal_pose, -1));
        bool swapped = false;

        const double STEP_LEN = 0.11;
        const float DD_RAD = 1.55f;

        auto step_tree = [&](std::vector<RRTNode>& tr, int from_idx, const Pose& goal_q, int max_steps) -> int {
            int cur = from_idx;
            for (int s = 0; s < max_steps; ++s) {
                Pose from = tr[cur].to_pose();
                double d = pose_dist(from, goal_q);
                if (d < 1e-4) break;
                double frac = std::min(1.0, STEP_LEN / d);
                Pose cand = pose_interp(from, goal_q, frac);
                bool retracted = false;
                if (!scene.is_valid_fast(cand, req_clr)) {
                    if (!scene.retract_fast(cand, req_clr + 0.001, 4)) {
                        tr[cur].dd_rad = DD_RAD;
                        break;
                    }
                    if (pose_dist(from, cand) > STEP_LEN * 1.9) {
                        tr[cur].dd_rad = DD_RAD;
                        break;
                    }
                    retracted = true;
                }
                if (!scene.valid_edge_fast(from, cand, req_clr)) {
                    tr[cur].dd_rad = DD_RAD;
                    break;
                }
                tr.push_back(RRTNode::from_pose(cand, cur));
                cur = (int)tr.size() - 1;
                if (frac >= 0.999 || retracted) break;
            }
            return cur;
        };

        for (int iter = 0; iter < 400000 && !solved.load(std::memory_order_relaxed); ++iter) {
            // Restart tree if > 30,000 nodes so NN stays blazing fast (< 5 us)!
            if (treeA.size() > 30000 || treeB.size() > 30000) {
                treeA.clear(); treeB.clear();
                treeA.push_back(RRTNode::from_pose(start_pose, -1));
                treeB.push_back(RRTNode::from_pose(goal_pose, -1));
                swapped = false;
            }

            Pose q_rand = sample_target();
            int nearA = nearest_node(treeA, q_rand);
            if (pose_dist(treeA[nearA].to_pose(), q_rand) > treeA[nearA].dd_rad) continue;

            int newA = step_tree(treeA, nearA, q_rand, 6);
            if (newA != nearA) {
                Pose target = treeA[newA].to_pose();
                int nearB = nearest_node(treeB, target);
                int newB = step_tree(treeB, nearB, target, 8);
                Pose reachedB = treeB[newB].to_pose();
                if (pose_dist(reachedB, target) <= STEP_LEN * 1.5 &&
                    scene.valid_edge_exact(reachedB, target, 0.0015)) {
                    // Reconstruct & verify entire path!
                    std::vector<Pose> pA, pB;
                    for (int k = newA; k != -1; k = treeA[k].parent) pA.push_back(treeA[k].to_pose());
                    std::reverse(pA.begin(), pA.end());
                    for (int k = newB; k != -1; k = treeB[k].parent) pB.push_back(treeB[k].to_pose());
                    std::vector<Pose> full;
                    if (!swapped) {
                        full = pA;
                        full.insert(full.end(), pB.begin(), pB.end());
                    } else {
                        std::reverse(pB.begin(), pB.end());
                        std::reverse(pA.begin(), pA.end());
                        full = pB;
                        full.insert(full.end(), pA.begin(), pA.end());
                    }
                    double min_c = 1.0;
                    for (size_t i = 0; i + 1 < full.size(); ++i) {
                        min_c = std::min(min_c, scene.edge_min_clearance_exact(full[i], full[i + 1]));
                    }
                    if (min_c >= 0.0010) {
                        auto dt_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                            std::chrono::steady_clock::now() - t_begin).count();
                        std::lock_guard<std::mutex> lk(sol_mtx);
                        std::printf("[Thread %d] SOLVED in %lld ms! iter=%d, treeA=%zu, treeB=%zu, raw_nodes=%zu, exact_min_clr=%.5f m\n",
                                    tid, (long long)dt_ms, iter, treeA.size(), treeB.size(), full.size(), min_c);
                        std::fflush(stdout);
                        if (min_c > best_path_clr) {
                            best_path_clr = min_c;
                            best_raw_path = full;
                        }
                        solved.store(true);
                        break;
                    }
                }
            }

            // ALWAYS keep treeA as the SMALLER tree so both grow equally!
            if (treeB.size() < treeA.size()) {
                std::swap(treeA, treeB);
                swapped = !swapped;
            }

            if (tid == 0 && iter % 10000 == 0 && iter > 0) {
                auto dt_s = std::chrono::duration_cast<std::chrono::milliseconds>(
                    std::chrono::steady_clock::now() - t_begin).count() / 1000.0;
                std::printf("[Progress %.1fs] iter=%d, treeA=%zu, treeB=%zu\n",
                            dt_s, iter, treeA.size(), treeB.size());
                std::fflush(stdout);
            }
        }
    }

    if (best_raw_path.empty()) {
        std::printf("FAILED to find path within iteration limit!\n");
        return 1;
    }

    // Post-process: subdivide, polish clearance, find earliest escape ray, shortcut, DP discretize!
    std::vector<Pose> path;
    path.push_back(best_raw_path[0]);
    for (size_t i = 0; i + 1 < best_raw_path.size(); ++i) {
        double dp = (best_raw_path[i + 1].p - best_raw_path[i].p).norm();
        double dq = quat_angle(best_raw_path[i].q, best_raw_path[i + 1].q);
        int n_sub = std::max({1, (int)std::ceil(dp / 0.04), (int)std::ceil(dq / 0.08)});
        for (int s = 1; s <= n_sub; ++s) {
            path.push_back(pose_interp(best_raw_path[i], best_raw_path[i + 1], (double)s / n_sub));
        }
    }

    auto compute_bottleneck = [&](const std::vector<Pose>& pth) {
        double mc = 1.0;
        for (size_t i = 0; i + 1 < pth.size(); ++i) {
            mc = std::min(mc, scene.edge_min_clearance_exact(pth[i], pth[i + 1]));
        }
        return mc;
    };

    double init_bn = compute_bottleneck(path);
    std::printf("Initial subdivided path: %zu waypoints, bottleneck clearance = %.5f m\n", path.size(), init_bn);
    std::fflush(stdout);

    for (int pass = 0; pass < 25; ++pass) {
        for (size_t i = 1; i + 1 < path.size(); ++i) {
            double old_c = std::min(scene.edge_min_clearance_exact(path[i - 1], path[i]),
                                    scene.edge_min_clearance_exact(path[i], path[i + 1]));
            Pose mid_p = pose_interp(path[i - 1], path[i + 1], 0.5);
            Pose cand = pose_interp(path[i], mid_p, 0.35);
            double target_push = std::min(0.032, old_c + 0.008);
            scene.retract_fast(cand, target_push, 3);
            double new_c = std::min(scene.edge_min_clearance_exact(path[i - 1], cand),
                                    scene.edge_min_clearance_exact(cand, path[i + 1]));
            if (new_c >= std::min(0.024, old_c)) {
                path[i] = cand;
            } else if (old_c < 0.024) {
                Pose push_p = path[i];
                if (scene.retract_fast(push_p, old_c + 0.006, 3)) {
                    double pc = std::min(scene.edge_min_clearance_exact(path[i - 1], push_p),
                                         scene.edge_min_clearance_exact(push_p, path[i + 1]));
                    if (pc > old_c) path[i] = push_p;
                }
            }
        }
    }

    double polished_bn = compute_bottleneck(path);
    std::printf("After clearance polishing: bottleneck clearance = %.5f m\n", polished_bn);
    std::fflush(stdout);

    // Truncate at earliest waypoint with >= 65mm straight-line infinity escape!
    for (size_t i = 0; i < path.size(); ++i) {
        Vec3 dir; double rclr;
        if (scene.check_infinity_escape(path[i], 0.065, &dir, &rclr)) {
            std::printf("Wide 65mm straight-line escape at waypoint %zu/%zu (ray_clr=%.4f m, dir=[%.3f, %.3f, %.3f])\n",
                        i, path.size() - 1, rclr, dir.x, dir.y, dir.z);
            if (i + 1 < path.size()) path.resize(i + 1);
            break;
        }
    }

    // Shortcut path preserving clearance >= keep_clr
    double keep_clr = std::min(0.020, polished_bn - 0.0005);
    std::mt19937_64 srng(42);
    for (int it = 0; it < 1200 && path.size() > 2; ++it) {
        size_t i = srng() % (path.size() - 1);
        size_t j = i + 2 + (srng() % std::max<size_t>(1, path.size() - i - 1));
        if (j >= path.size()) continue;
        if (scene.valid_edge_exact(path[i], path[j], keep_clr) &&
            scene.edge_min_clearance_exact(path[i], path[j]) >= keep_clr) {
            std::vector<Pose> next_p;
            for (size_t k = 0; k <= i; ++k) next_p.push_back(path[k]);
            double dp = (path[j].p - path[i].p).norm();
            double dq = quat_angle(path[i].q, path[j].q);
            int n_sub = std::max({1, (int)std::ceil(dp / 0.045), (int)std::ceil(dq / 0.09)});
            for (int s = 1; s < n_sub; ++s) {
                next_p.push_back(pose_interp(path[i], path[j], (double)s / n_sub));
            }
            for (size_t k = j; k < path.size(); ++k) next_p.push_back(path[k]);
            path = std::move(next_p);
        }
    }

    // DP discretization into legal `move` steps (dp <= 0.095 m, dq <= 0.190 rad)
    const double MAX_DP = 0.095;
    const double MAX_DQ = 0.190;
    size_t N = path.size();
    std::vector<int> dp_cost(N, 1e9);
    std::vector<int> dp_prev(N, -1);
    dp_cost[0] = 0;
    for (size_t i = 0; i < N; ++i) {
        if (dp_cost[i] >= 1e8) continue;
        for (size_t j = i + 1; j < N; ++j) {
            double d_lin = (path[j].p - path[i].p).norm();
            double d_ang = quat_angle(path[i].q, path[j].q);
            if ((d_lin > MAX_DP || d_ang > MAX_DQ) && j > i + 1) continue;
            if (d_lin <= MAX_DP && d_ang <= MAX_DQ) {
                if (dp_cost[i] + 1 < dp_cost[j]) {
                    if (scene.valid_edge_exact(path[i], path[j], keep_clr) &&
                        scene.edge_min_clearance_exact(path[i], path[j]) >= keep_clr) {
                        dp_cost[j] = dp_cost[i] + 1;
                        dp_prev[j] = (int)i;
                    }
                }
            }
        }
        if (i + 1 < N && dp_cost[i + 1] >= 1e8) {
            dp_cost[i + 1] = dp_cost[i] + 1;
            dp_prev[i + 1] = (int)i;
        }
    }

    std::vector<Pose> move_plan;
    for (int cur = (int)N - 1; cur != -1; cur = dp_prev[cur]) {
        move_plan.push_back(path[cur]);
    }
    std::reverse(move_plan.begin(), move_plan.end());

    double final_bn = compute_bottleneck(move_plan);
    std::printf("\n=== FINAL MOVE PLAN: %zu move steps (+1 grab = %zu total actions / 198), EXACT bottleneck clearance = %.5f m ===\n",
                move_plan.size() - 1, move_plan.size(), final_bn);

    FILE* jf = std::fopen("/app/planned_path.json", "w");
    std::fprintf(jf, "{\n  \"bottleneck_clearance_m\": %.6f,\n  \"num_moves\": %zu,\n  \"waypoints\": [\n",
                 final_bn, move_plan.size() - 1);
    for (size_t i = 0; i < move_plan.size(); ++i) {
        const auto& wp = move_plan[i];
        double edge_c = (i == 0) ? scene.min_clearance_exact(wp, 0.5) : scene.edge_min_clearance_exact(move_plan[i - 1], wp);
        double d_lin = (i == 0) ? 0.0 : (wp.p - move_plan[i - 1].p).norm();
        double d_ang = (i == 0) ? 0.0 : quat_angle(move_plan[i - 1].q, wp.q);
        Vec3 edir = {0, 0, 1}; double eclr = -1.0;
        scene.check_infinity_escape(wp, 0.005, &edir, &eclr);
        std::printf("  Step %2zu: pos=[%7.4f, %7.4f, %7.4f] quat=[%7.4f, %7.4f, %7.4f, %7.4f] | dp=%.4f dq=%.4f | edge_clr=%.4fm | esc_clr=%.4fm\n",
                    i, wp.p.x, wp.p.y, wp.p.z, wp.q.w, wp.q.x, wp.q.y, wp.q.z, d_lin, d_ang, edge_c, eclr);
        std::fprintf(jf, "    {\"pos\": [%.7f, %.7f, %.7f], \"quat\": [%.7f, %.7f, %.7f, %.7f], \"edge_clr\": %.6f, \"esc_clr\": %.6f}%s\n",
                     wp.p.x, wp.p.y, wp.p.z, wp.q.w, wp.q.x, wp.q.y, wp.q.z, edge_c, eclr,
                     (i + 1 < move_plan.size()) ? "," : "");
    }
    std::fprintf(jf, "  ]\n}\n");
    std::fclose(jf);
    std::printf("Saved /app/planned_path.json!\n");
    return 0;
}

#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <mutex>
#include <omp.h>
#include <random>
#include <unordered_map>
#include <vector>

struct Vec3 {
    double x, y, z;
    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(double s) const { return {x * s, y * s, z * s}; }
    double dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
    Vec3 cross(const Vec3& o) const {
        return {y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x};
    }
    double norm2() const { return x * x + y * y + z * z; }
    double norm() const { return std::sqrt(norm2()); }
};

struct Quat {
    double w, x, y, z;
    Quat normalized() const {
        double n = std::sqrt(w * w + x * x + y * y + z * z);
        if (n < 1e-12) return {1, 0, 0, 0};
        if (w < 0) n = -n;
        return {w / n, x / n, y / n, z / n};
    }
    Quat operator*(const Quat& o) const {
        return {
            w * o.w - x * o.x - y * o.y - z * o.z,
            w * o.x + x * o.w + y * o.z - z * o.y,
            w * o.y - x * o.z + y * o.w + z * o.x,
            w * o.z + x * o.y - y * o.x + z * o.w
        };
    }
};

struct Mat3 {
    double m[9];
    static Mat3 from_quat(const Quat& q) {
        double xx = q.x * q.x, yy = q.y * q.y, zz = q.z * q.z;
        double xy = q.x * q.y, xz = q.x * q.z, yz = q.y * q.z;
        double wx = q.w * q.x, wy = q.w * q.y, wz = q.w * q.z;
        return {{
            1.0 - 2.0 * (yy + zz), 2.0 * (xy - wz),       2.0 * (xz + wy),
            2.0 * (xy + wz),       1.0 - 2.0 * (xx + zz), 2.0 * (yz - wx),
            2.0 * (xz - wy),       2.0 * (yz + wx),       1.0 - 2.0 * (xx + yy)
        }};
    }
    Vec3 apply(double px, double py, double pz) const {
        return {
            m[0] * px + m[1] * py + m[2] * pz,
            m[3] * px + m[4] * py + m[5] * pz,
            m[6] * px + m[7] * py + m[8] * pz
        };
    }
};

inline double quat_angle(const Quat& a, const Quat& b) {
    double d = std::abs(a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z);
    if (d >= 1.0) return 0.0;
    return 2.0 * std::acos(d);
}

Quat quat_slerp(const Quat& a, Quat b, double t) {
    double d = a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
    if (d < 0.0) {
        b = {-b.w, -b.x, -b.y, -b.z};
        d = -d;
    }
    if (d > 0.9995) {
        Quat r = {a.w + t * (b.w - a.w), a.x + t * (b.x - a.x),
                  a.y + t * (b.y - a.y), a.z + t * (b.z - a.z)};
        return r.normalized();
    }
    double theta = std::acos(d);
    double st = std::sin(theta);
    double wa = std::sin((1.0 - t) * theta) / st;
    double wb = std::sin(t * theta) / st;
    return Quat{wa * a.w + wb * b.w, wa * a.x + wb * b.x,
                wa * a.y + wb * b.y, wa * a.z + wb * b.z}.normalized();
}

Quat quat_from_rotvec(const Vec3& rv) {
    double ang = rv.norm();
    if (ang < 1e-10) return Quat{1.0, 0.5 * rv.x, 0.5 * rv.y, 0.5 * rv.z}.normalized();
    double s = std::sin(0.5 * ang) / ang;
    return Quat{std::cos(0.5 * ang), rv.x * s, rv.y * s, rv.z * s}.normalized();
}

struct Pose {
    Vec3 p;
    Quat q;
};

Pose pose_interp(const Pose& a, const Pose& b, double t) {
    return {a.p + (b.p - a.p) * t, quat_slerp(a.q, b.q, t)};
}

struct SphereNode {
    float cx, cy, cz, r;
    int32_t start, count;
};

struct LeafPt {
    float x, y, z;
};

struct Scene {
    uint32_t nx, ny, nz;
    double h, inv_h;
    Vec3 origin, a_min, a_max;
    std::vector<float> sdf;

    uint32_t cnx, cny, cnz;
    double ch, cinv_h;
    std::vector<float> csdf;

    std::vector<SphereNode> top;
    std::vector<SphereNode> mid;
    std::vector<LeafPt> leaves;

    std::vector<SphereNode> fast_top;
    std::vector<LeafPt> fast_leaves;

    // 28-segment spines for Gauss Linking Integral!
    std::vector<Vec3> spine_a_mid, spine_a_tan;
    std::vector<Vec3> spine_b_mid_local, spine_b_tan_local;

    void load(const char* path, const char* spine_path) {
        FILE* f = std::fopen(path, "rb");
        if (!f) { std::perror("fopen"); std::exit(1); }
        uint32_t magic;
        if (std::fread(&magic, 4, 1, f) != 1 || magic != 0x414C5048) std::exit(1);
        if (std::fread(&nx, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&ny, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&nz, 4, 1, f) != 1) std::exit(1);
        double hdr[10];
        if (std::fread(hdr, sizeof(double), 10, f) != 10) std::exit(1);
        h = hdr[0]; inv_h = 1.0 / h;
        origin = {hdr[1], hdr[2], hdr[3]};
        a_min = {hdr[4], hdr[5], hdr[6]};
        a_max = {hdr[7], hdr[8], hdr[9]};
        uint32_t n_top, n_mid, n_leaves;
        if (std::fread(&n_top, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&n_mid, 4, 1, f) != 1) std::exit(1);
        if (std::fread(&n_leaves, 4, 1, f) != 1) std::exit(1);
        size_t n_vox = (size_t)nx * ny * nz;
        sdf.resize(n_vox);
        if (std::fread(sdf.data(), sizeof(float), n_vox, f) != n_vox) std::exit(1);
        top.resize(n_top);
        if (std::fread(top.data(), sizeof(SphereNode), n_top, f) != n_top) std::exit(1);
        mid.resize(n_mid);
        if (std::fread(mid.data(), sizeof(SphereNode), n_mid, f) != n_mid) std::exit(1);
        leaves.resize(n_leaves);
        if (std::fread(leaves.data(), sizeof(LeafPt), n_leaves, f) != n_leaves) std::exit(1);
        std::fclose(f);

        cnx = (nx + 1) / 2; cny = (ny + 1) / 2; cnz = (nz + 1) / 2;
        ch = h * 2.0; cinv_h = 1.0 / ch;
        csdf.resize((size_t)cnx * cny * cnz);
        for (uint32_t i = 0; i < cnx; ++i) {
            uint32_t si = std::min(nx - 1, i * 2);
            for (uint32_t j = 0; j < cny; ++j) {
                uint32_t sj = std::min(ny - 1, j * 2);
                for (uint32_t k = 0; k < cnz; ++k) {
                    uint32_t sk = std::min(nz - 1, k * 2);
                    csdf[((size_t)i * cny + j) * cnz + k] = sdf[((size_t)si * ny * nz + (size_t)sj * nz + sk)];
                }
            }
        }

        fast_top = top;
        for (auto& ft : fast_top) {
            int f_start = (int)fast_leaves.size();
            for (int mi = ft.start; mi < ft.start + ft.count; ++mi) {
                const auto& ms = mid[mi];
                fast_leaves.push_back({ms.cx, ms.cy, ms.cz});
                if (ms.count > 0) fast_leaves.push_back(leaves[ms.start]);
                if (ms.count > 2) fast_leaves.push_back(leaves[ms.start + ms.count / 2]);
            }
            ft.start = f_start;
            ft.count = (int)fast_leaves.size() - f_start;
        }

        FILE* sf = std::fopen(spine_path, "r");
        if (!sf) { std::perror("fopen spines"); std::exit(1); }
        int m_pts = 0;
        if (std::fscanf(sf, "%d", &m_pts) != 1) std::exit(1);
        std::vector<Vec3> pa(m_pts), pb(m_pts);
        for (int i = 0; i < m_pts; ++i) std::fscanf(sf, "%lf %lf %lf", &pa[i].x, &pa[i].y, &pa[i].z);
        for (int i = 0; i < m_pts; ++i) std::fscanf(sf, "%lf %lf %lf", &pb[i].x, &pb[i].y, &pb[i].z);
        std::fclose(sf);
        for (int i = 0; i + 1 < m_pts; ++i) {
            spine_a_mid.push_back((pa[i] + pa[i + 1]) * 0.5);
            spine_a_tan.push_back(pa[i + 1] - pa[i]);
            spine_b_mid_local.push_back((pb[i] + pb[i + 1]) * 0.5);
            spine_b_tan_local.push_back(pb[i + 1] - pb[i]);
        }

        std::printf("Loaded Scene: %ux%ux%u SDF, %zu fast_leaves, %zu spine segs\n",
                    nx, ny, nz, fast_leaves.size(), spine_a_mid.size());
    }

    // Ultra-fast Gauss Linking Integral (~0.6 microseconds!)
    inline double abs_gln(const Pose& pose) const {
        Mat3 R = Mat3::from_quat(pose.q);
        size_t M = spine_a_mid.size();
        Vec3 bm[32], bt[32];
        for (size_t j = 0; j < M; ++j) {
            bm[j] = R.apply(spine_b_mid_local[j].x, spine_b_mid_local[j].y, spine_b_mid_local[j].z) + pose.p;
            bt[j] = R.apply(spine_b_tan_local[j].x, spine_b_tan_local[j].y, spine_b_tan_local[j].z);
        }
        double sum = 0.0;
        for (size_t i = 0; i < M; ++i) {
            const Vec3& am = spine_a_mid[i];
            const Vec3& at = spine_a_tan[i];
            for (size_t j = 0; j < M; ++j) {
                double rx = am.x - bm[j].x, ry = am.y - bm[j].y, rz = am.z - bm[j].z;
                double d2 = rx * rx + ry * ry + rz * rz;
                double inv_d3 = 1.0 / (d2 * std::sqrt(d2) + 1e-6);
                // (at x bt[j]) . r
                double cx = at.y * bt[j].z - at.z * bt[j].y;
                double cy = at.z * bt[j].x - at.x * bt[j].z;
                double cz = at.x * bt[j].y - at.y * bt[j].x;
                sum += (cx * rx + cy * ry + cz * rz) * inv_d3;
            }
        }
        return std::abs(sum) * (1.0 / (4.0 * 3.14159265358979323846));
    }

    inline double eval_csdf(double wx, double wy, double wz) const {
        double fx = (wx - origin.x) * cinv_h;
        double fy = (wy - origin.y) * cinv_h;
        double fz = (wz - origin.z) * cinv_h;
        if (fx >= 0.0 && fy >= 0.0 && fz >= 0.0) {
            int ix = (int)fx, iy = (int)fy, iz = (int)fz;
            if (ix < (int)cnx - 1 && iy < (int)cny - 1 && iz < (int)cnz - 1) {
                double tx = fx - ix, ty = fy - iy, tz = fz - iz;
                size_t sx = (size_t)cny * cnz, sy = (size_t)cnz;
                const float* p = csdf.data() + (size_t)ix * sx + (size_t)iy * sy + (size_t)iz;
                double c00 = p[0] + tx * (p[sx] - p[0]);
                double c01 = p[1] + tx * (p[sx + 1] - p[1]);
                double c10 = p[sy] + tx * (p[sx + sy] - p[sy]);
                double c11 = p[sy + 1] + tx * (p[sx + sy + 1] - p[sy + 1]);
                return (c00 + ty * (c10 - c00)) + tz * ((c01 + ty * (c11 - c01)) - (c00 + ty * (c10 - c00)));
            }
        }
        double dx = std::max({0.0, a_min.x - wx, wx - a_max.x});
        double dy = std::max({0.0, a_min.y - wy, wy - a_max.y});
        double dz = std::max({0.0, a_min.z - wz, wz - a_max.z});
        return std::sqrt(dx * dx + dy * dy + dz * dz);
    }

    inline double eval_sdf(double wx, double wy, double wz) const {
        double fx = (wx - origin.x) * inv_h;
        double fy = (wy - origin.y) * inv_h;
        double fz = (wz - origin.z) * inv_h;
        if (fx >= 0.0 && fy >= 0.0 && fz >= 0.0) {
            int ix = (int)fx, iy = (int)fy, iz = (int)fz;
            if (ix < (int)nx - 1 && iy < (int)ny - 1 && iz < (int)nz - 1) {
                double tx = fx - ix, ty = fy - iy, tz = fz - iz;
                size_t sx = (size_t)ny * nz, sy = (size_t)nz;
                const float* p = sdf.data() + (size_t)ix * sx + (size_t)iy * sy + (size_t)iz;
                double c00 = p[0] + tx * (p[sx] - p[0]);
                double c01 = p[1] + tx * (p[sx + 1] - p[1]);
                double c10 = p[sy] + tx * (p[sx + sy] - p[sy]);
                double c11 = p[sy + 1] + tx * (p[sx + sy + 1] - p[sy + 1]);
                return (c00 + ty * (c10 - c00)) + tz * ((c01 + ty * (c11 - c01)) - (c00 + ty * (c10 - c00)));
            }
        }
        double dx = std::max({0.0, a_min.x - wx, wx - a_max.x});
        double dy = std::max({0.0, a_min.y - wy, wy - a_max.y});
        double dz = std::max({0.0, a_min.z - wz, wz - a_max.z});
        return std::sqrt(dx * dx + dy * dy + dz * dz);
    }

    inline Vec3 eval_cgrad(double wx, double wy, double wz) const {
        double eps = 0.010;
        Vec3 g = {
            eval_csdf(wx + eps, wy, wz) - eval_csdf(wx - eps, wy, wz),
            eval_csdf(wx, wy + eps, wz) - eval_csdf(wx, wy - eps, wz),
            eval_csdf(wx, wy, wz + eps) - eval_csdf(wx, wy, wz - eps)
        };
        double n = g.norm();
        return (n < 1e-9) ? Vec3{0, 0, 1} : (g * (1.0 / n));
    }

    inline bool in_workspace(const Pose& pose) const {
        return !(pose.p.x < -0.74 || pose.p.x > 3.14 ||
                 pose.p.y < -0.74 || pose.p.y > 3.14 ||
                 pose.p.z < -0.74 || pose.p.z > 3.14);
    }

    inline bool is_valid_fast(const Pose& pose, double thresh) const {
        if (!in_workspace(pose)) return false;
        Mat3 R = Mat3::from_quat(pose.q);
        double eff = thresh + 0.0020;
        for (const auto& ft : fast_top) {
            Vec3 wt = R.apply(ft.cx, ft.cy, ft.cz) + pose.p;
            double dt = eval_csdf(wt.x, wt.y, wt.z);
            if (dt - ft.r >= eff) continue;
            if (dt < -0.05) return false;
            int end = ft.start + ft.count;
            for (int i = ft.start; i < end; ++i) {
                const auto& lf = fast_leaves[i];
                Vec3 wl = R.apply(lf.x, lf.y, lf.z) + pose.p;
                if (eval_csdf(wl.x, wl.y, wl.z) < eff) return false;
            }
        }
        return true;
    }

    bool retract_fast(Pose& pose, double thresh, int max_iters = 5) const {
        double eff = thresh + 0.0020;
        for (int it = 0; it < max_iters; ++it) {
            if (!in_workspace(pose)) return false;
            Mat3 R = Mat3::from_quat(pose.q);
            double margin = eff + 0.018;
            Vec3 force = {0, 0, 0}, torque = {0, 0, 0};
            double w_sum = 0.0, worst_d = 1e9;

            for (const auto& ft : fast_top) {
                Vec3 wt = R.apply(ft.cx, ft.cy, ft.cz) + pose.p;
                double dt = eval_csdf(wt.x, wt.y, wt.z);
                if (dt - ft.r >= margin) continue;
                if (dt < -0.05) return false;
                int end = ft.start + ft.count;
                double min_t = 1e9;
                Vec3 worst_rel = {0, 0, 0};
                for (int i = ft.start; i < end; ++i) {
                    const auto& lf = fast_leaves[i];
                    Vec3 rel = R.apply(lf.x, lf.y, lf.z);
                    Vec3 wl = rel + pose.p;
                    double dl = eval_csdf(wl.x, wl.y, wl.z);
                    if (dl < -0.04) return false;
                    if (dl < min_t) { min_t = dl; worst_rel = rel; }
                }
                if (min_t < worst_d) worst_d = min_t;
                if (min_t < margin) {
                    Vec3 wl = worst_rel + pose.p;
                    Vec3 g = eval_cgrad(wl.x, wl.y, wl.z);
                    double pen = margin - min_t;
                    double w = pen * pen + 1e-4;
                    force = force + g * w;
                    torque = torque + worst_rel.cross(g) * w;
                    w_sum += w;
                }
            }
            if (worst_d >= eff) return true;
            if (worst_d < -0.035 || w_sum < 1e-9) return false;
            force = force * (1.0 / w_sum);
            torque = torque * (1.0 / w_sum);
            double fn = force.norm(), tn = torque.norm();
            double need = std::max(0.004, (eff - worst_d) + 0.003);
            if (fn > 1e-6) pose.p = pose.p + force * (std::min(0.020, need) / fn);
            if (tn > 1e-6) {
                Quat dq = quat_from_rotvec(torque * (std::min(0.035, need * 1.4) / tn));
                pose.q = (dq * pose.q).normalized();
            }
        }
        return is_valid_fast(pose, thresh);
    }

    bool valid_edge_fast(const Pose& a, const Pose& b, double thresh) const {
        double dp = (b.p - a.p).norm();
        double dq = quat_angle(a.q, b.q);
        int ns = std::max({2, (int)std::ceil(dp / 0.016), (int)std::ceil(dq / 0.032)});
        if (!is_valid_fast(pose_interp(a, b, 0.5), thresh)) return false;
        for (int i = 1; i <= ns; ++i) {
            if (i * 2 == ns) continue;
            if (!is_valid_fast(pose_interp(a, b, (double)i / ns), thresh)) return false;
        }
        return true;
    }

    bool is_valid_exact(const Pose& pose, double thresh) const {
        if (!in_workspace(pose)) return false;
        Mat3 R = Mat3::from_quat(pose.q);
        for (const auto& ts : top) {
            Vec3 wt = R.apply(ts.cx, ts.cy, ts.cz) + pose.p;
            double dt = eval_sdf(wt.x, wt.y, wt.z);
            if (dt - ts.r >= thresh) continue;
            int m_end = ts.start + ts.count;
            for (int mi = ts.start; mi < m_end; ++mi) {
                const auto& ms = mid[mi];
                Vec3 wm = R.apply(ms.cx, ms.cy, ms.cz) + pose.p;
                double dm = eval_sdf(wm.x, wm.y, wm.z);
                if (dm - ms.r >= thresh) continue;
                if (dm < thresh) return false;
                int l_end = ms.start + ms.count;
                for (int li = ms.start; li < l_end; ++li) {
                    const auto& lf = leaves[li];
                    Vec3 wl = R.apply(lf.x, lf.y, lf.z) + pose.p;
                    if (eval_sdf(wl.x, wl.y, wl.z) < thresh) return false;
                }
            }
        }
        return true;
    }

    double min_clearance_exact(const Pose& pose, double max_cap = 0.25) const {
        if (!in_workspace(pose)) return -1.0;
        Mat3 R = Mat3::from_quat(pose.q);
        double best = max_cap;
        for (const auto& ts : top) {
            Vec3 wt = R.apply(ts.cx, ts.cy, ts.cz) + pose.p;
            double dt = eval_sdf(wt.x, wt.y, wt.z);
            if (dt - ts.r >= best) continue;
            int m_end = ts.start + ts.count;
            for (int mi = ts.start; mi < m_end; ++mi) {
                const auto& ms = mid[mi];
                Vec3 wm = R.apply(ms.cx, ms.cy, ms.cz) + pose.p;
                double dm = eval_sdf(wm.x, wm.y, wm.z);
                if (dm - ms.r >= best) continue;
                int l_end = ms.start + ms.count;
                for (int li = ms.start; li < l_end; ++li) {
                    const auto& lf = leaves[li];
                    Vec3 wl = R.apply(lf.x, lf.y, lf.z) + pose.p;
                    double dl = eval_sdf(wl.x, wl.y, wl.z);
                    if (dl < best) best = dl;
                }
            }
        }
        return best;
    }

    bool valid_edge_exact(const Pose& a, const Pose& b, double thresh) const {
        double dp = (b.p - a.p).norm();
        double dq = quat_angle(a.q, b.q);
        int ns = std::max({2, (int)std::ceil(dp / 0.006), (int)std::ceil(dq / 0.012)});
        for (int i = 1; i <= ns; ++i) {
            if (!is_valid_exact(pose_interp(a, b, (double)i / ns), thresh)) return false;
        }
        double t_lin = dp / 0.1, t_ang = dq / 0.1, t_max = std::max(t_lin, t_ang);
        if (t_max > 1e-6 && std::abs(t_lin - t_ang) > 0.015) {
            for (int i = 1; i < ns; ++i) {
                double t = t_max * ((double)i / ns);
                double ul = (t_lin > 1e-8) ? std::min(1.0, t / t_lin) : 1.0;
                double ua = (t_ang > 1e-8) ? std::min(1.0, t / t_ang) : 1.0;
                Pose pu = {a.p + (b.p - a.p) * ul, quat_slerp(a.q, b.q, ua)};
                if (!is_valid_exact(pu, thresh)) return false;
            }
        }
        return true;
    }

    double edge_min_clearance_exact(const Pose& a, const Pose& b) const {
        double dp = (b.p - a.p).norm();
        double dq = quat_angle(a.q, b.q);
        int ns = std::max({2, (int)std::ceil(dp / 0.006), (int)std::ceil(dq / 0.012)});
        double worst = 1.0;
        double t_lin = dp / 0.1, t_ang = dq / 0.1, t_max = std::max(t_lin, t_ang);
        for (int i = 0; i <= ns; ++i) {
            double u = (double)i / ns;
            worst = std::min(worst, min_clearance_exact(pose_interp(a, b, u), worst));
            if (t_max > 1e-6 && std::abs(t_lin - t_ang) > 0.015) {
                double t = t_max * u;
                double ul = (t_lin > 1e-8) ? std::min(1.0, t / t_lin) : 1.0;
                double ua = (t_ang > 1e-8) ? std::min(1.0, t / t_ang) : 1.0;
                Pose pu = {a.p + (b.p - a.p) * ul, quat_slerp(a.q, b.q, ua)};
                worst = std::min(worst, min_clearance_exact(pu, worst));
            }
        }
        return worst;
    }

    bool check_infinity_escape(const Pose& pose, double escape_thresh, Vec3* best_dir_out = nullptr, double* best_clr_out = nullptr) const {
        const int N_DIRS = 120;
        const double golden = 3.14159265358979323846 * (3.0 - std::sqrt(5.0));
        double best_ray_clr = -1.0;
        Vec3 best_dir = {0, 0, 1};

        Mat3 R = Mat3::from_quat(pose.q);
        Vec3 bmin = {1e9, 1e9, 1e9}, bmax = {-1e9, -1e9, -1e9};
        for (const auto& ts : top) {
            Vec3 w = R.apply(ts.cx, ts.cy, ts.cz) + pose.p;
            bmin.x = std::min(bmin.x, w.x - ts.r); bmax.x = std::max(bmax.x, w.x + ts.r);
            bmin.y = std::min(bmin.y, w.y - ts.r); bmax.y = std::max(bmax.y, w.y + ts.r);
            bmin.z = std::min(bmin.z, w.z - ts.r); bmax.z = std::max(bmax.z, w.z + ts.r);
        }

        auto eval_ray = [&](const Vec3& dir, bool exact, double req) -> double {
            double rmin = 1.0;
            for (double s = 0.0; s <= 4.2; s += 0.030) {
                Vec3 shift = dir * s;
                if ((bmin.x + shift.x > a_max.x + 0.25 && dir.x >= 0) ||
                    (bmax.x + shift.x < a_min.x - 0.25 && dir.x <= 0) ||
                    (bmin.y + shift.y > a_max.y + 0.25 && dir.y >= 0) ||
                    (bmax.y + shift.y < a_min.y - 0.25 && dir.y <= 0) ||
                    (bmin.z + shift.z > a_max.z + 0.25 && dir.z >= 0) ||
                    (bmax.z + shift.z < a_min.z - 0.25 && dir.z <= 0)) {
                    break;
                }
                Vec3 sp = pose.p + shift;
                if (!exact) {
                    for (const auto& ft : fast_top) {
                        Vec3 wt = R.apply(ft.cx, ft.cy, ft.cz) + sp;
                        double dt = eval_csdf(wt.x, wt.y, wt.z);
                        if (dt - ft.r >= rmin) continue;
                        int end = ft.start + ft.count;
                        for (int k = ft.start; k < end; ++k) {
                            const auto& lf = fast_leaves[k];
                            Vec3 wl = R.apply(lf.x, lf.y, lf.z) + sp;
                            double dl = eval_csdf(wl.x, wl.y, wl.z);
                            if (dl < req) return -1.0;
                            if (dl < rmin) rmin = dl;
                        }
                    }
                } else {
                    for (const auto& ts : top) {
                        Vec3 wt = R.apply(ts.cx, ts.cy, ts.cz) + sp;
                        double dt = eval_sdf(wt.x, wt.y, wt.z);
                        if (dt - ts.r >= rmin) continue;
                        int m_end = ts.start + ts.count;
                        for (int mi = ts.start; mi < m_end; ++mi) {
                            const auto& ms = mid[mi];
                            Vec3 wm = R.apply(ms.cx, ms.cy, ms.cz) + sp;
                            double dm = eval_sdf(wm.x, wm.y, wm.z);
                            if (dm - ms.r >= rmin) continue;
                            if (dm < req) return -1.0;
                            int l_end = ms.start + ms.count;
                            for (int li = ms.start; li < l_end; ++li) {
                                const auto& lf = leaves[li];
                                Vec3 wl = R.apply(lf.x, lf.y, lf.z) + sp;
                                double dl = eval_sdf(wl.x, wl.y, wl.z);
                                if (dl < req) return -1.0;
                                if (dl < rmin) rmin = dl;
                            }
                        }
                    }
                }
            }
            return rmin;
        };

        for (int i = 0; i < N_DIRS; ++i) {
            double y = 1.0 - (2.0 * i + 1.0) / N_DIRS;
            double rad = std::sqrt(std::max(0.0, 1.0 - y * y));
            double phi = golden * i;
            Vec3 dir = {std::cos(phi) * rad, y, std::sin(phi) * rad};
            double cc = eval_ray(dir, false, std::max(escape_thresh + 0.002, best_ray_clr));
            if (cc >= escape_thresh) {
                double ce = eval_ray(dir, true, escape_thresh);
                if (ce > best_ray_clr) { best_ray_clr = ce; best_dir = dir; }
            }
        }
        if (best_dir_out) *best_dir_out = best_dir;
        if (best_clr_out) *best_clr_out = best_ray_clr;
        return best_ray_clr >= escape_thresh;
    }
};

struct TreeNode {
    Pose pose;
    int parent;
    float gln;
};

struct Cell {
    std::vector<int> nodes;
    int selects = 0;
    float min_gln = 10.0f;
};

static inline uint64_t hash_cell(const Pose& p, double gln, double cell_p, double cell_q) {
    int64_t ix = (int64_t)std::floor((p.p.x + 5.0) / cell_p);
    int64_t iy = (int64_t)std::floor((p.p.y + 5.0) / cell_p);
    int64_t iz = (int64_t)std::floor((p.p.z + 5.0) / cell_p);
    int64_t ig = (int64_t)std::floor(gln / 0.05);
    int64_t qx = (int64_t)std::floor((p.q.x + 1.1) / cell_q);
    int64_t qy = (int64_t)std::floor((p.q.y + 1.1) / cell_q);
    int64_t qz = (int64_t)std::floor((p.q.z + 1.1) / cell_q);
    uint64_t h = 1469598103934665603ULL;
    auto mix = [&](int64_t v) {
        h ^= (uint64_t)(v + 0x9e3779b97f4a7c15ULL);
        h *= 1099511628211ULL;
    };
    mix(ix); mix(iy); mix(iz); mix(ig); mix(qx); mix(qy); mix(qz);
    return h;
}

int main() {
    Scene scene;
    scene.load("/app/planner_data.bin", "/app/spines28.txt");

    Pose start_pose = {{1.2, 0.36, 0.28}, {1.0, 0.0, 0.0, 0.0}};
    double start_gln = scene.abs_gln(start_pose);
    std::printf("Start clearance: %.5f m, start |GLN| = %.5f\n",
                scene.min_clearance_exact(start_pose, 0.5), start_gln);
    std::fflush(stdout);

    auto t_begin = std::chrono::steady_clock::now();
    std::atomic<bool> solved{false};
    std::atomic<int> best_gln_milli{(int)(start_gln * 1000.0)};
    std::mutex sol_mtx;
    std::vector<Pose> best_raw_path;
    double best_path_clr = -1.0;

    // 10-thread Topology-Guided KPIECE (Gauss Linking Integral + SDF-Wrench Retraction)!
    #pragma omp parallel num_threads(10)
    {
        int tid = omp_get_thread_num();
        double req_clr = 0.0015 + 0.0005 * (tid % 6); // +2mm fast buffer => 3.5mm .. 6.0mm!
        double cell_p = 0.10 + 0.015 * (tid % 4);
        double cell_q = 0.35 + 0.05 * (tid % 3);
        double gln_weight = 10.0 + 3.0 * (tid % 4);   // portfolio of GLN greediness vs exploration!

        std::mt19937_64 rng(20261115 + tid * 2654435761ULL);
        std::uniform_real_distribution<double> u01(0.0, 1.0);
        std::normal_distribution<double> gauss(0.0, 1.0);

        std::vector<TreeNode> tree;
        tree.reserve(200000);
        tree.push_back({start_pose, -1, (float)start_gln});

        std::unordered_map<uint64_t, int> cell_map;
        cell_map.reserve(80000);
        std::vector<Cell> cells;
        cells.reserve(80000);

        // Keep explicit elite pool of lowest-GLN cells for fast breakthroughs!
        std::vector<int> elite_cells;

        auto add_node_to_cells = [&](int node_idx) -> bool {
            const auto& nd = tree[node_idx];
            uint64_t hc = hash_cell(nd.pose, nd.gln, cell_p, cell_q);
            auto it = cell_map.find(hc);
            if (it == cell_map.end()) {
                int cid = (int)cells.size();
                cell_map[hc] = cid;
                cells.push_back({{node_idx}, 0, nd.gln});
                if (nd.gln < 0.95f) elite_cells.push_back(cid);
                return true;
            } else {
                auto& c = cells[it->second];
                if (nd.gln < c.min_gln) c.min_gln = nd.gln;
                if (c.nodes.size() < 8) c.nodes.push_back(node_idx);
                else if (nd.gln <= tree[c.nodes[0]].gln) c.nodes[rng() % 8] = node_idx;
                return false;
            }
        };
        add_node_to_cells(0);

        for (int iter = 0; iter < 2000000 && !solved.load(std::memory_order_relaxed); ++iter) {
            int n_cells = (int)cells.size();
            int best_cid = 0;
            double best_score = 1e18;

            // 40% sample from elite low-GLN cells (if non-empty), 60% tournament across all cells!
            bool use_elite = (!elite_cells.empty() && u01(rng) < 0.45);
            int k_tourn = 20;
            for (int t = 0; t < k_tourn; ++t) {
                int cid;
                if (use_elite && t < 12) {
                    cid = elite_cells[rng() % elite_cells.size()];
                } else {
                    cid = (int)(rng() % n_cells);
                }
                const auto& c = cells[cid];
                double score = c.selects * 2.2 + 0.4 * (double)c.nodes.size() + gln_weight * c.min_gln;
                if (score < best_score) {
                    best_score = score;
                    best_cid = cid;
                }
            }

            cells[best_cid].selects++;
            const auto& cnodes = cells[best_cid].nodes;
            int cur_idx = cnodes[rng() % cnodes.size()];

            Vec3 dir_p = {gauss(rng), gauss(rng), gauss(rng)};
            Vec3 dir_r = {gauss(rng), gauss(rng), gauss(rng)};
            double np = dir_p.norm(), nr = dir_r.norm();
            dir_p = (np < 1e-6) ? Vec3{0, 1, 0} : (dir_p * (1.0 / np));
            dir_r = (nr < 1e-6) ? Vec3{1, 0, 0} : (dir_r * (1.0 / nr));

            double mode = u01(rng);
            double step_p = (mode < 0.15) ? 0.015 : 0.080;
            double step_r = (mode > 0.85) ? 0.025 : 0.160;

            for (int walk = 0; walk < 6; ++walk) {
                const Pose& from = tree[cur_idx].pose;
                Pose cand = {
                    from.p + dir_p * step_p,
                    (quat_from_rotvec(dir_r * step_r) * from.q).normalized()
                };

                if (!scene.is_valid_fast(cand, req_clr)) {
                    if (!scene.retract_fast(cand, req_clr + 0.001, 5)) break;
                    if ((cand.p - from.p).norm() > 0.14 || quat_angle(from.q, cand.q) > 0.28) break;
                    Vec3 dp_act = cand.p - from.p;
                    if (dp_act.norm() > 0.015) dir_p = dp_act * (1.0 / dp_act.norm());
                }

                if (!scene.valid_edge_fast(from, cand, req_clr)) break;

                double g = scene.abs_gln(cand);
                int g_milli = (int)(g * 1000.0);
                int prev_best = best_gln_milli.load(std::memory_order_relaxed);
                while (g_milli < prev_best && !best_gln_milli.compare_exchange_weak(prev_best, g_milli)) {}

                int new_idx = (int)tree.size();
                tree.push_back({cand, cur_idx, (float)g});
                bool is_new = add_node_to_cells(new_idx);

                // If GLN decreased, continue walking eagerly! If GLN jumped up a lot, stop walk early!
                float prev_g = tree[cur_idx].gln;
                cur_idx = new_idx;

                if (is_new && g < 0.32) {
                    Vec3 esc_dir; double esc_clr;
                    if (scene.check_infinity_escape(cand, 0.060, &esc_dir, &esc_clr)) {
                        std::vector<Pose> raw;
                        for (int k = cur_idx; k != -1; k = tree[k].parent) raw.push_back(tree[k].pose);
                        std::reverse(raw.begin(), raw.end());

                        double min_c = 1.0;
                        for (size_t i = 0; i + 1 < raw.size(); ++i) {
                            min_c = std::min(min_c, scene.edge_min_clearance_exact(raw[i], raw[i + 1]));
                        }
                        if (min_c >= 0.0010) {
                            auto dt_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                                std::chrono::steady_clock::now() - t_begin).count();
                            std::lock_guard<std::mutex> lk(sol_mtx);
                            std::printf("[Thread %d] SOLVED in %lld ms! iter=%d, tree=%zu, cells=%zu, raw_len=%zu, min_clr=%.5f m, gln=%.4f, esc_clr=%.4f m\n",
                                        tid, (long long)dt_ms, iter, tree.size(), cells.size(), raw.size(), min_c, g, esc_clr);
                            std::fflush(stdout);
                            if (min_c > best_path_clr) {
                                best_path_clr = min_c;
                                best_raw_path = raw;
                            }
                            solved.store(true);
                            break;
                        }
                    }
                }
                if (g > prev_g + 0.08) break;
            }

            if (tid == 0 && iter % 15000 == 0 && iter > 0) {
                auto dt_s = std::chrono::duration_cast<std::chrono::milliseconds>(
                    std::chrono::steady_clock::now() - t_begin).count() / 1000.0;
                std::printf("[Progress %.1fs] iter=%d, tree=%zu, cells=%zu, elite=%zu, global_min_GLN=%.3f\n",
                            dt_s, iter, tree.size(), cells.size(), elite_cells.size(),
                            best_gln_milli.load() / 1000.0);
                std::fflush(stdout);
            }
        }
    }

    if (best_raw_path.empty()) {
        std::printf("FAILED to find path within iteration limit! Lowest |GLN| reached: %.3f\n",
                    best_gln_milli.load() / 1000.0);
        return 1;
    }

    // Subdivide, polish clearance, truncate at earliest 65mm escape, shortcut, DP discretize!
    std::vector<Pose> path;
    path.push_back(best_raw_path[0]);
    for (size_t i = 0; i + 1 < best_raw_path.size(); ++i) {
        double dp = (best_raw_path[i + 1].p - best_raw_path[i].p).norm();
        double dq = quat_angle(best_raw_path[i].q, best_raw_path[i + 1].q);
        int n_sub = std::max({1, (int)std::ceil(dp / 0.04), (int)std::ceil(dq / 0.08)});
        for (int s = 1; s <= n_sub; ++s) {
            path.push_back(pose_interp(best_raw_path[i], best_raw_path[i + 1], (double)s / n_sub));
        }
    }

    auto compute_bottleneck = [&](const std::vector<Pose>& pth) {
        double mc = 1.0;
        for (size_t i = 0; i + 1 < pth.size(); ++i) {
            mc = std::min(mc, scene.edge_min_clearance_exact(pth[i], pth[i + 1]));
        }
        return mc;
    };

    double init_bn = compute_bottleneck(path);
    std::printf("Initial subdivided path: %zu waypoints, bottleneck clearance = %.5f m\n", path.size(), init_bn);
    std::fflush(stdout);

    for (int pass = 0; pass < 25; ++pass) {
        for (size_t i = 1; i + 1 < path.size(); ++i) {
            double old_c = std::min(scene.edge_min_clearance_exact(path[i - 1], path[i]),
                                    scene.edge_min_clearance_exact(path[i], path[i + 1]));
            Pose mid_p = pose_interp(path[i - 1], path[i + 1], 0.5);
            Pose cand = pose_interp(path[i], mid_p, 0.35);
            double target_push = std::min(0.032, old_c + 0.008);
            scene.retract_fast(cand, target_push, 3);
            double new_c = std::min(scene.edge_min_clearance_exact(path[i - 1], cand),
                                    scene.edge_min_clearance_exact(cand, path[i + 1]));
            if (new_c >= std::min(0.024, old_c)) {
                path[i] = cand;
            } else if (old_c < 0.024) {
                Pose push_p = path[i];
                if (scene.retract_fast(push_p, old_c + 0.006, 3)) {
                    double pc = std::min(scene.edge_min_clearance_exact(path[i - 1], push_p),
                                         scene.edge_min_clearance_exact(push_p, path[i + 1]));
                    if (pc > old_c) path[i] = push_p;
                }
            }
        }
    }
    {
        Vec3 edir; double eclr;
        if (scene.check_infinity_escape(path.back(), 0.020, &edir, &eclr)) {
            Pose extra = {path.back().p + edir * 0.09, path.back().q};
            if (scene.in_workspace(extra) && scene.valid_edge_exact(path.back(), extra, 0.025)) {
                path.push_back(extra);
            }
        }
    }

    double polished_bn = compute_bottleneck(path);
    std::printf("After clearance polishing: bottleneck clearance = %.5f m\n", polished_bn);
    std::fflush(stdout);

    for (size_t i = 0; i < path.size(); ++i) {
        Vec3 dir; double rclr;
        if (scene.check_infinity_escape(path[i], 0.065, &dir, &rclr)) {
            std::printf("Wide 65mm straight-line escape at waypoint %zu/%zu (ray_clr=%.4f m, dir=[%.3f, %.3f, %.3f])\n",
                        i, path.size() - 1, rclr, dir.x, dir.y, dir.z);
            if (i + 1 < path.size()) path.resize(i + 1);
            break;
        }
    }

    double keep_clr = std::min(0.020, polished_bn - 0.0005);
    std::mt19937_64 srng(42);
    for (int it = 0; it < 1200 && path.size() > 2; ++it) {
        size_t i = srng() % (path.size() - 1);
        size_t j = i + 2 + (srng() % std::max<size_t>(1, path.size() - i - 1));
        if (j >= path.size()) continue;
        if (scene.valid_edge_exact(path[i], path[j], keep_clr) &&
            scene.edge_min_clearance_exact(path[i], path[j]) >= keep_clr) {
            std::vector<Pose> next_p;
            for (size_t k = 0; k <= i; ++k) next_p.push_back(path[k]);
            double dp = (path[j].p - path[i].p).norm();
            double dq = quat_angle(path[i].q, path[j].q);
            int n_sub = std::max({1, (int)std::ceil(dp / 0.045), (int)std::ceil(dq / 0.09)});
            for (int s = 1; s < n_sub; ++s) {
                next_p.push_back(pose_interp(path[i], path[j], (double)s / n_sub));
            }
            for (size_t k = j; k < path.size(); ++k) next_p.push_back(path[k]);
            path = std::move(next_p);
        }
    }

    const double MAX_DP = 0.095;
    const double MAX_DQ = 0.190;
    size_t N = path.size();
    std::vector<int> dp_cost(N, 1e9);
    std::vector<int> dp_prev(N, -1);
    dp_cost[0] = 0;
    for (size_t i = 0; i < N; ++i) {
        if (dp_cost[i] >= 1e8) continue;
        for (size_t j = i + 1; j < N; ++j) {
            double d_lin = (path[j].p - path[i].p).norm();
            double d_ang = quat_angle(path[i].q, path[j].q);
            if ((d_lin > MAX_DP || d_ang > MAX_DQ) && j > i + 1) continue;
            if (d_lin <= MAX_DP && d_ang <= MAX_DQ) {
                if (dp_cost[i] + 1 < dp_cost[j]) {
                    if (scene.valid_edge_exact(path[i], path[j], keep_clr) &&
                        scene.edge_min_clearance_exact(path[i], path[j]) >= keep_clr) {
                        dp_cost[j] = dp_cost[i] + 1;
                        dp_prev[j] = (int)i;
                    }
                }
            }
        }
        if (i + 1 < N && dp_cost[i + 1] >= 1e8) {
            dp_cost[i + 1] = dp_cost[i] + 1;
            dp_prev[i + 1] = (int)i;
        }
    }

    std::vector<Pose> move_plan;
    for (int cur = (int)N - 1; cur != -1; cur = dp_prev[cur]) {
        move_plan.push_back(path[cur]);
    }
    std::reverse(move_plan.begin(), move_plan.end());

    double final_bn = compute_bottleneck(move_plan);
    std::printf("\n=== FINAL MOVE PLAN: %zu move steps (+1 grab = %zu total actions / 198), EXACT bottleneck clearance = %.5f m ===\n",
                move_plan.size() - 1, move_plan.size(), final_bn);

    FILE* jf = std::fopen("/app/planned_path.json", "w");
    std::fprintf(jf, "{\n  \"bottleneck_clearance_m\": %.6f,\n  \"num_moves\": %zu,\n  \"waypoints\": [\n",
                 final_bn, move_plan.size() - 1);
    for (size_t i = 0; i < move_plan.size(); ++i) {
        const auto& wp = move_plan[i];
        double edge_c = (i == 0) ? scene.min_clearance_exact(wp, 0.5) : scene.edge_min_clearance_exact(move_plan[i - 1], wp);
        double d_lin = (i == 0) ? 0.0 : (wp.p - move_plan[i - 1].p).norm();
        double d_ang = (i == 0) ? 0.0 : quat_angle(move_plan[i - 1].q, wp.q);
        Vec3 edir = {0, 0, 1}; double eclr = -1.0;
        scene.check_infinity_escape(wp, 0.005, &edir, &eclr);
        std::printf("  Step %2zu: pos=[%7.4f, %7.4f, %7.4f] quat=[%7.4f, %7.4f, %7.4f, %7.4f] | dp=%.4f dq=%.4f | edge_clr=%.4fm | esc_clr=%.4fm\n",
                    i, wp.p.x, wp.p.y, wp.p.z, wp.q.w, wp.q.x, wp.q.y, wp.q.z, d_lin, d_ang, edge_c, eclr);
        std::fprintf(jf, "    {\"pos\": [%.7f, %.7f, %.7f], \"quat\": [%.7f, %.7f, %.7f, %.7f], \"edge_clr\": %.6f, \"esc_clr\": %.6f}%s\n",
                     wp.p.x, wp.p.y, wp.p.z, wp.q.w, wp.q.x, wp.q.y, wp.q.z, edge_c, eclr,
                     (i + 1 < move_plan.size()) ? "," : "");
    }
    std::fprintf(jf, "  ]\n}\n");
    std::fclose(jf);
    std::printf("Saved /app/planned_path.json!\n");
    return 0;
}

