// Keep explicit elite pools of low-GLN cells for fast breakthroughs!
std::vector<int> elite_cells;       // gln < 0.55
std::vector<int> super_elite_cells; // gln < 0.35

auto add_node_to_cells = [&](int node_idx) -> bool {
    const auto& nd = tree[node_idx];
    uint64_t hc = hash_cell(nd.pose, nd.gln, cell_p, cell_q);
    auto it = cell_map.find(hc);
    if (it == cell_map.end()) {
        int cid = (int)cells.size();
        cell_map[hc] = cid;
        cells.push_back({{node_idx}, 0, nd.gln});
        if (nd.gln < 0.55f) elite_cells.push_back(cid);
        if (nd.gln < 0.35f) super_elite_cells.push_back(cid);
        return true;
