        for (int i = 0; i <= ns; ++i) {
            double u = (double)i / ns;
            worst = std::min(worst, min_clr(pose_interp(a, b, u), worst));
            if (t_max > 1e-6 && std::abs(t_lin - t_ang) > 0.01) {
                double t = t_max * u;
                double ul = (t_lin > 1e-8) ? std::min(1.0, t / t_lin) : 1.0;
                double ua = (t_ang > 1e-8) ? std::min(1.0, t / t_ang) : 1.0;
                worst = std::min(worst, min_clr({a.p + (b.p - a.p) * ul, quat_slerp(a.q, b.q, ua)}, worst));
            }
        }
        return worst;
    }

    bool check_escape(const Pose& pose, Vec3& best_dir, double& best_clr) const {
        const int N_DIRS = 200;
        const double golden = 3.14159265358979323846 * (3.0 - std::sqrt(5.0));
        best_clr = -1.0; best_dir = {0, 0, 1};
        Mat3 R = Mat3::from_quat(pose.q);
        Vec3 bmin = {1e9,1e9,1e9}, bmax = {-1e9,-1e9,-1e9};
        for (const auto& ts : top) {
            Vec3 w = R.apply(ts.cx, ts.cy, ts.cz) + pose.p;
            bmin.x = std::min(bmin.x, w.x - ts.r); bmax.x = std::max(bmax.x, w.x + ts.r);
            bmin.y = std::min(bmin.y, w.y - ts.r); bmax.y = std::max(bmax.y, w.y + ts.r);
            bmin.z = std::min(bmin.z, w.z - ts.r); bmax.z = std::max(bmax.z, w.z + ts.r);
        }
        for (int i = 0; i < N_DIRS; ++i) {
            double y = 1.0 - (2.0 * i + 1.0) / N_DIRS;
            double rad = std::sqrt(std::max(0.0, 1.0 - y * y));
            double phi = golden * i;
            Vec3 dir = {std::cos(phi) * rad, y, std::sin(phi) * rad};
            double rmin = 1.0; bool ok = true;
            for (double s = 0.0; s <= 4.2; s += 0.025) {
                Vec3 shift = dir * s;
                if ((bmin.x + shift.x > a_max.x + 0.25 && dir.x >= 0) ||
                    (bmax.x + shift.x < a_min.x - 0.25 && dir.x <= 0) ||
                    (bmin.y + shift.y > a_max.y + 0.25 && dir.y >= 0) ||
                    (bmax.y + shift.y < a_min.y - 0.25 && dir.y <= 0) ||
                    (bmin.z + shift.z > a_max.z + 0.25 && dir.z >= 0) ||
                    (bmax.z + shift.z < a_min.z - 0.25 && dir.z <= 0)) break;
                Vec3 sp = pose.p + shift;
                double cut = std::max(0.005, best_clr);
                for (const auto& ts : top) {
                    Vec3 wt = R.apply(ts.cx, ts.cy, ts.cz) + sp;
                    if (eval_sdf(wt.x, wt.y, wt.z) - ts.r >= std::min(rmin, 1.0)) continue;
                    for (int mi = ts.start; mi < ts.start + ts.count; ++mi) {
                        const auto& ms = mid[mi];
                        Vec3 wm = R.apply(ms.cx, ms.cy, ms.cz) + sp;
                        double dm = eval_sdf(wm.x, wm.y, wm.z);
                        if (dm - ms.r >= rmin) continue;
                        if (dm < cut) { ok = false; break; }
                        for (int li = ms.start; li < ms.start + ms.count; ++li) {
                            const auto& lf = leaves[li];
                            Vec3 wl = R.apply(lf.x, lf.y, lf.z) + sp;
                            double dl = eval_sdf(wl.x, wl.y, wl.z);
                            if (dl < cut) { ok = false; break; }
                            if (dl < rmin) rmin = dl;
                        }
                        if (!ok) break;
                    }
                    if (!ok) break;
                }
                if (!ok) break;
            }
            if (ok && rmin > best_clr) { best_clr = rmin; best_dir = dir; }
        }
        return best_clr > 0.005;
    }
};

int main() {
    Scene scene;
    scene.load("/app/planner_data.bin");

    // Parse waypoints from /app/planned_path.json
    std::ifstream ifs("/app/planned_path.json");
    std::string content((std::istreambuf_iterator<char>(ifs)), std::istreambuf_iterator<char>());
    std::vector<Pose> raw;
    size_t pos = 0;
    while ((pos = content.find("\"pos\": [", pos)) != std::string::npos) {
        pos += 8;
        double px, py, pz, qw, qx, qy, qz;
        std::sscanf(content.c_str() + pos, "%lf, %lf, %lf", &px, &py, &pz);
        pos = content.find("\"quat\": [", pos) + 9;
        std::sscanf(content.c_str() + pos, "%lf, %lf, %lf, %lf", &qw, &qx, &qy, &qz);
        raw.push_back({{px, py, pz}, Quat{qw, qx, qy, qz}.normalized()});
    }
    std::printf("Loaded %zu raw waypoints from /app/planned_path.json\n", raw.size());

    // Subdivide finely (<= 0.025m / 0.05 rad) so trajectory can curve cleanly around tight corners!
    std::vector<Pose> path;
    path.push_back(raw[0]);
    for (size_t i = 0; i + 1 < raw.size(); ++i) {
        double dp = (raw[i + 1].p - raw[i].p).norm();
        double dq = quat_angle(raw[i].q, raw[i + 1].q);
        int ns = std::max({1, (int)std::ceil(dp / 0.025), (int)std::ceil(dq / 0.05)});
        for (int s = 1; s <= ns; ++s) path.push_back(pose_interp(raw[i], raw[i + 1], (double)s / ns));
    }

    // Also append 3 extra steps along the escape ray at the end so final escape clearance > 0.12m!
    {
        Vec3 edir; double eclr;
        if (scene.check_escape(path.back(), edir, eclr)) {
            std::printf("Initial end escape clr = %.4f m along [%.3f, %.3f, %.3f]\n", eclr, edir.x, edir.y, edir.z);
            for (int k = 0; k < 6; ++k) {
                Pose nxt = {path.back().p + edir * 0.04, path.back().q};
                if (scene.in_ws(nxt)) path.push_back(nxt);
            }
        }
    }

    auto calc_bn = [&](const std::vector<Pose>& pth) {
        double mc = 1.0;
        size_t ne = pth.size() - 1;
        #pragma omp parallel for reduction(min:mc) schedule(dynamic) num_threads(10)
        for (size_t i = 0; i < ne; ++i) mc = std::min(mc, scene.edge_clr(pth[i], pth[i + 1]));
        return mc;
    };

    std::printf("Before exact polishing (%zu pts): bottleneck = %.5f m\n", path.size(), calc_bn(path));
    std::fflush(stdout);

    // 120 passes of Exact Softmin Gradient Ascent + Stochastic Coordinate Hill-Climbing!
    for (int pass = 0; pass < 120; ++pass) {
        double step_sz = (pass < 40) ? 0.006 : ((pass < 80) ? 0.003 : 0.0012);
        for (int parity = 1; parity <= 2; ++parity) {
            size_t end_i = path.size() - 1;
            #pragma omp parallel for schedule(dynamic) num_threads(10)
            for (size_t i = parity; i < end_i; i += 2) {
                double c_old = std::min(scene.edge_clr(path[i - 1], path[i]),
                                        scene.edge_clr(path[i], path[i + 1]));
                if (c_old >= 0.030) {
                    // Gently smooth high-clearance parts
                    Pose sm = pose_interp(path[i], pose_interp(path[i - 1], path[i + 1], 0.5), 0.3);
                    double cs = std::min(scene.edge_clr(path[i - 1], sm), scene.edge_clr(sm, path[i + 1]));
                    if (cs >= 0.028) path[i] = sm;
                    continue;
                }
                // Try exact softmin push + slight laplacian blend!
                Pose pushed = scene.push_away(path[i], step_sz);
                Pose blended = pose_interp(pushed, pose_interp(path[i - 1], path[i + 1], 0.5), 0.15);
                for (const Pose& cand : {pushed, blended}) {
                    if ((cand.p - path[i - 1].p).norm() > 0.08 || (cand.p - path[i + 1].p).norm() > 0.08) continue;
                    double cn = std::min(scene.edge_clr(path[i - 1], cand), scene.edge_clr(cand, path[i + 1]));
                    if (cn > c_old) {
                        path[i] = cand;
                        c_old = cn;
                    }
                }
                // Also try 6 random local perturbations around tightest nodes (< 0.015m) to escape saddle points!
                if (c_old < 0.015) {
                    std::mt19937_64 rng(pass * 100003ULL + i * 997ULL);
                    std::normal_distribution<double> g(0.0, 1.0);
                    for (int t = 0; t < 6; ++t) {
                        Pose rnd = {
                            path[i].p + Vec3{g(rng), g(rng), g(rng)} * (step_sz * 0.8),
                            (quat_from_rotvec(Vec3{g(rng), g(rng), g(rng)} * (step_sz * 1.5)) * path[i].q).normalized()
                        };
                        if (!scene.in_ws(rnd)) continue;
                        if (scene.min_clr(rnd, c_old + 0.001) <= c_old) continue;
                        double cr = std::min(scene.edge_clr(path[i - 1], rnd), scene.edge_clr(rnd, path[i + 1]));
                        if (cr > c_old) {
                            path[i] = rnd;
                            c_old = cr;
                        }
                    }
                }
            }
        }
        if ((pass + 1) % 20 == 0) {
            std::printf("  Pass %3d: exact bottleneck clearance = %+.5f m\n", pass + 1, calc_bn(path));
            std::fflush(stdout);
        }
    }

    double polished_bn = calc_bn(path);
    std::printf("After exact optimization: bottleneck clearance = %+.5f m!\n", polished_bn);

    // DP discretization into minimum number of legal `move` steps preserving >= min(0.018, polished_bn - 0.0005)!
    double keep_clr = std::min(0.018, polished_bn - 0.0004);
    const double MAX_DP = 0.095;
    const double MAX_DQ = 0.190;
    size_t N = path.size();
    std::vector<int> dp_cost(N, 1e9), dp_prev(N, -1);
    dp_cost[0] = 0;

    for (size_t i = 0; i < N; ++i) {
        if (dp_cost[i] >= 1e8) continue;
        #pragma omp parallel for schedule(dynamic) num_threads(10)
        for (size_t j = i + 1; j < N; ++j) {
            double d_lin = (path[j].p - path[i].p).norm();
            double d_ang = quat_angle(path[i].q, path[j].q);
            if ((d_lin > MAX_DP || d_ang > MAX_DQ) && j > i + 1) continue;
            if (d_lin <= MAX_DP && d_ang <= MAX_DQ) {
                if (scene.edge_clr(path[i], path[j]) >= keep_clr) {
                    #pragma omp critical
                    {
                        if (dp_cost[i] + 1 < dp_cost[j]) {
                            dp_cost[j] = dp_cost[i] + 1;
                            dp_prev[j] = (int)i;
                        }
                    }
                }
            }
        }
        if (i + 1 < N && dp_cost[i + 1] >= 1e8) {
            dp_cost[i + 1] = dp_cost[i] + 1;
            dp_prev[i + 1] = (int)i;
        }
    }

    std::vector<Pose> move_plan;
    for (int cur = (int)N - 1; cur != -1; cur = dp_prev[cur]) move_plan.push_back(path[cur]);
    std::reverse(move_plan.begin(), move_plan.end());

    double final_bn = calc_bn(move_plan);
    Vec3 final_edir; double final_eclr;
    scene.check_escape(move_plan.back(), final_edir, final_eclr);

    std::printf("\n=== OPTIMIZED FINAL MOVE PLAN: %zu move steps (+1 grab = %zu / 198 actions), EXACT bottleneck = %+.5f m, final esc_clr = %.4f m ===\n",
                move_plan.size() - 1, move_plan.size(), final_bn, final_eclr);

    FILE* jf = std::fopen("/app/polished_path.json", "w");
    std::fprintf(jf, "{\n  \"bottleneck_clearance_m\": %.6f,\n  \"num_moves\": %zu,\n  \"waypoints\": [\n",
                 final_bn, move_plan.size() - 1);
    for (size_t i = 0; i < move_plan.size(); ++i) {
        const auto& wp = move_plan[i];
        double ec = (i == 0) ? scene.min_clr(wp, 0.5) : scene.edge_clr(move_plan[i - 1], wp);
        double dl = (i == 0) ? 0.0 : (wp.p - move_plan[i - 1].p).norm();
        double da = (i == 0) ? 0.0 : quat_angle(move_plan[i - 1].q, wp.q);
        Vec3 ed; double el; scene.check_escape(wp, ed, el);
        std::printf("  Step %2zu: pos=[%7.4f, %7.4f, %7.4f] quat=[%7.4f, %7.4f, %7.4f, %7.4f] | dp=%.4f dq=%.4f | edge_clr=%+.4fm | esc_clr=%+.4fm\n",
                    i, wp.p.x, wp.p.y, wp.p.z, wp.q.w, wp.q.x, wp.q.y, wp.q.z, dl, da, ec, el);
        std::fprintf(jf, "    {\"pos\": [%.7f, %.7f, %.7f], \"quat\": [%.7f, %.7f, %.7f, %.7f], \"edge_clr\": %.6f, \"esc_clr\": %.6f}%s\n",
                     wp.p.x, wp.p.y, wp.p.z, wp.q.w, wp.q.x, wp.q.y, wp.q.z, ec, el,
                     (i + 1 < move_plan.size()) ? "," : "");
    }
    std::fprintf(jf, "  ]\n}\n");
    std::fclose(jf);
    std::printf("Saved /app/polished_path.json!\n");
    return 0;
}

